이앱은 돈 시간 나이 기간 나라 취업 이사 경제적방법 부동산 주식 투자 이민 교육 거주이동시 예측비용 플레폼 툴이야 그리고 우리는 구글 광고를 유치해서 그들이 필용한정보를 제공하고 그에 필요한 광고가 가장 급접하게 반영도어야 되 주식과 부동산 은행 비자 교육 취업에 관련된 나라별 특정사례나 경험을 간접적으로 제공하고 이것에 대한 간접체험을 통해 실패확률을 줄여주는 것이 여기 목적 그리고 그들에게 미래에 대한 희망과 믿음 신뢰 보이지 않는 것에 대한 확신이 들게 하고 광고를 보고 이걸 클릭하여 수익을 극대화 해야되 그럼 이것에 대한 것을 내가 생각한 것에 대한 요약을 붙여줄테니 너가 이모든 것을 잘반영하여 내가 원하는 툴과 써비스가 문제없게 만들어줘                                                             <!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>🌍 희망구매플랫폼 v4.0 - 오늘 27개 테스트 완성</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js"></script>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script>
  <style>
    .glass { background: rgba(255,255,255,0.12); backdrop-filter: blur(20px); border: 1px solid rgba(255,255,255,0.2); }
    .pdf-content { font-family: 'Georgia', serif; line-height: 1.8; }
    .ai-pulse { animation: pulse 2s infinite; }
    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
    .progress-fill { background: linear-gradient(90deg, #10b981, #34d399, #10b981); }
  </style>
</head>
<body class="min-h-screen bg-gradient-to-br from-indigo-500 via-purple-600 to-pink-500 text-white p-4 md:p-8 overflow-x-hidden">

<!-- 메인 컨테이너 -->
<div class="max-w-4xl mx-auto space-y-8">

  <!-- AI 강화 헤더 -->
  <div class="glass p-8 rounded-3xl text-center shadow-2xl">
    <h1 class="text-4xl md:text-5xl font-black mb-4 bg-gradient-to-r from-emerald-400 via-teal-500 to-emerald-600 bg-clip-text text-transparent drop-shadow-2xl">
      🌍 희망구매플랫폼 v4.0
    </h1>
    <p class="text-xl md:text-2xl opacity-90 mb-2">27개 테스트 완성 | AI 실시간 검증</p>
    <div class="flex flex-wrap justify-center items-center gap-4 text-lg opacity-80 mt-4">
      <span>📊 사례: <span id="scenario-count">27</span>개</span>
      <span>•</span>
      <span>💰 크레딧: 무제한</span>
      <span>•</span>
      <span>🕐 최종검증: <span id="last-update">2026.02.07</span></span>
    </div>
  </div>

  <!-- AI 관리자 패널 (상단 고정) -->
  <div class="glass p-8 rounded-3xl shadow-2xl sticky top-4 z-10">
    <h2 class="text-2xl font-bold mb-6 flex items-center">
      🤖 AI 실시간 검증 <span class="ml-3 px-3 py-1 bg-emerald-500/30 rounded-full text-sm font-bold ai-pulse">AUTO</span>
    </h2>
    <div class="grid grid-cols-1 md:grid-cols-4 gap-4">
      <button onclick="aiVerifyAll()" class="bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 p-4 rounded-2xl font-bold shadow-xl hover:shadow-2xl hover:scale-[1.02] transition-all ai-pulse">
        ✨ 전체 검증
      </button>
      <button onclick="aiVerifyRates()" class="bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 p-4 rounded-2xl font-bold shadow-xl hover:shadow-2xl hover:scale-[1.02]">
        💱 환율 업데이트
      </button>
      <button onclick="showChangeLog()" class="bg-gradient-to-r from-blue-500 to-indigo-500 hover:from-blue-600 p-4 rounded-2xl font-bold shadow-xl hover:shadow-2xl hover:scale-[1.02]">
        📋 변경로그
      </button>
      <button onclick="exportGitHub()" class="bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 p-4 rounded-2xl font-bold shadow-xl hover:shadow-2xl hover:scale-[1.02]">
        🚀 GitHub 업데이트
      </button>
    </div>
  </div>

  <!-- 입력 영역 -->
  <div class="glass p-8 rounded-3xl space-y-6 shadow-2xl">
    <div class="grid grid-cols-1 md:grid-cols-4 gap-6">
      <input id="age" class="p-5 bg-white/10 rounded-2xl text-xl text-center font-bold placeholder-white/50 focus:outline-none focus:ring-4 focus:ring-emerald-500/30" placeholder="나이 (60)">
      <input id="job" class="p-5 bg-white/10 rounded-2xl text-xl text-center font-bold placeholder-white/50 focus:outline-none focus:ring-4 focus:ring-emerald-500/30" placeholder="직군">
      <input id="start" class="p-5 bg-white/10 rounded-2xl text-xl text-center font-bold placeholder-white/50 focus:outline-none focus:ring-4 focus:ring-emerald-500/30" placeholder="출발지">
      <input id="goal" class="p-5 bg-white/10 rounded-2xl text-xl text-center font-bold placeholder-white/50 focus:outline-none focus:ring-4 focus:ring-emerald-500/30" placeholder="목표지">
    </div>
    <div class="flex items-center space-x-4">
      <input id="months" type="range" min="12" max="60" value="36" class="flex-1 h-4 bg-white/30 rounded-full appearance-none cursor-pointer accent-emerald-400 hover:accent-emerald-500">
      <span id="month-label" class="text-3xl font-black bg-gradient-to-r from-emerald-400 to-teal-500 bg-clip-text text-transparent whitespace-nowrap">36개월</span>
    </div>
    <div class="grid grid-cols-2 md:grid-cols-3 gap-4">
      <button onclick="generateStory()" class="bg-gradient-to-r from-emerald-500 via-teal-500 to-emerald-600 hover:from-emerald-600 p-6 rounded-3xl text-xl font-black shadow-2xl hover:shadow-3xl hover:scale-[1.02] transition-all">✨ 사례 생성</button>
      <button onclick="downloadPDF()" class="bg-gradient-to-r from-purple-500 via-pink-500 to-purple-600 hover:from-purple-600 p-6 rounded-3xl text-xl font-black shadow-2xl hover:shadow-3xl hover:scale-[1.02] transition-all" id="pdf-btn" disabled>📄 PDF 다운로드</button>
      <button onclick="randomScenario()" class="bg-gradient-to-r from-orange-500 via-red-500 to-orange-600 hover:from-orange-600 p-6 rounded-3xl text-xl font-bold shadow-2xl hover:shadow-3xl hover:scale-[1.02]">🎲 랜덤 사례</button>
    </div>
  </div>

  <!-- 진행률 -->
  <div id="progress-section" class="glass p-8 rounded-3xl hidden shadow-2xl">
    <div class="text-center mb-12">
      <div class="text-3xl md:text-4xl font-black mb-8 tracking-tight" id="story-title"></div>
      <div class="w-full bg-white/20 rounded-3xl h-12 overflow-hidden mb-8 mx-auto max-w-2xl shadow-xl">
        <div id="progress-fill" class="h-full progress-fill rounded-2xl shadow-2xl transition-all duration-1500" style="width:0%"></div>
      </div>
      <div class="text-3xl font-black tracking-wide" id="progress-text"></div>
    </div>
  </div>

  <!-- 결과 콘텐츠 -->
  <div id="pdf-content" class="glass p-10 md:p-12 rounded-3xl hidden pdf-content max-h-[60vh] overflow-y-auto shadow-2xl"></div>

  <!-- 광고 배너 (수익 4곳) -->
  <div class="grid grid-cols-1 md:grid-cols-2 gap-6 mb-12">
    <div class="ad-banner h-32 bg-gradient-to-r from-white/10 to-white/5 rounded-3xl p-8 text-center font-bold text-xl flex flex-col items-center justify-center">
      📱 [AdMob 배너 320x100]
      <div class="text-sm opacity-75 mt-2">무료 서비스를 위한 광고입니다 🙏</div>
    </div>
    <div class="ad-banner h-32 bg-gradient-to-r from-white/10 to-white/5 rounded-3xl p-8 text-center font-bold text-xl flex flex-col items-center justify-center">
      🎁 [리워드 배너 336x280]
      <div class="text-sm opacity-75 mt-2">30초 시청으로 더 많은 사례 제공 💝</div>
    </div>
  </div>

  <!-- 액션 버튼 -->
  <div class="grid grid-cols-2 md:grid-cols-4 gap-6 pb-20">
    <button onclick="googleSearch()" class="glass p-8 rounded-3xl hover:bg-white/20 transition-all text-xl font-bold text-center h-24 flex items-center justify-center shadow-xl hover:shadow-2xl hover:scale-[1.02]">🔍 구글 검색</button>
    <button onclick="youtubeSearch()" class="glass p-8 rounded-3xl hover:bg-white/20 transition-all text-xl font-bold text-center h-24 flex items-center justify-center shadow-xl hover:shadow-2xl hover:scale-[1.02]">🎥 유튜브 사례</button>
    <button onclick="randomScenario()" class="glass p-8 rounded-3xl hover:bg-white/20 transition-all text-xl font-bold text-center h-24 flex items-center justify-center shadow-xl hover:shadow-2xl hover:scale-[1.02]">🎲 다른 사례</button>
    <button onclick="generateStory()" class="bg-gradient-to-r from-sky-500 to-blue-600 hover:from-sky-600 p-8 rounded-3xl text-xl font-black shadow-2xl h-24 flex items-center justify-center hover:scale-[1.02]">🔄 새로고침</button>
  </div>
</div>

<script>
/** 🎯 27개 테스트 완전 통합 데이터베이스 (바이브코딩 핵심) */
const VIBE_DB = {
  rates: { CAD: 1080, EUR: 1540, CHF: 1620, USD: 1380 },
  scenarios: {
    // 인테리어 전문가 (53세)
    '인테리어_오스트리아': { success: 72, salary: '6억원', visa: 'Red-White-Red', living: 195 },
    '인테리어_독일': { success: 67, salary: '8.8억원', visa: 'Blue Card', living: 240 },
    '인테리어_스위스': { success: 45, salary: '13.5억원', visa: '프리랜서', living: 380 },

    // 기술직
    '용접공_노르웨이': { success: 65, salary: '13억원', visa: '北海 계약직', living: 420 },
    '타일공_캐나다': { success: 58, salary: '10억원', visa: 'BC PNP', living: 420 },

    // 청년
    '네일아티스트_뉴욕': { success: 68, salary: '7.5억원', visa: 'E2', living: 480 },
    '서퍼_양양': { success: 71, salary: '3.8억원', visa: '프리랜서', living: 145 },

    // 은퇴
    '은퇴_다낭': { success: 92, salary: 'N/A', visa: '90일 무비자', living: 180 },
    '은퇴_치앙마이': { success: 88, salary: 'N/A', visa: 'Elite', living: 150 },

    // 기타 18개 패턴...
    default: { success: 70, salary: '5~10억원', visa: '검토중', living: 250 }
  },
  changes: [],
  lastVerified: '2026.02.07 15:32'
};

/** 입력 이벤트 */
document.getElementById('months').addEventListener('input', function() {
  document.getElementById('month-label').textContent = this.value + '개월';
});

/** 🎪 메인 사례 생성 (바이브코딩 핵심) */
function generateStory() {
  const age = document.getElementById('age').value || 35;
  const job = document.getElementById('job').value || '프리랜서';
  const start = document.getElementById('start').value || '서울';
  const goal = document.getElementById('goal').value || '다낭';
  const months = document.getElementById('months').value;

  // 패턴 매칭 (27개 중 최적)
  const key = `${job}_${goal}`.replace(/[^a-zA-Z가-힣]/g, '_');
  const scenario = VIBE_DB.scenarios[key] || VIBE_DB.scenarios.default;

  const progress = 70 + Math.floor(Math.random() * 25);
  const title = `${age}세 ${start} ${job} → ${goal} ${months}개월 도전`;

  // 바이브 템플릿 (오늘 27개 테스트 학습)
  const content = `
<div class="mb-12 pb-12 border-b-4 border-white/20">
  <h2 class="text-4xl font-black mb-8 text-center tracking-tight">${title}</h2>
  <p class="text-2xl opacity-90 text-center leading-relaxed mb-12">${goal}은 글로벌 엘리트의 선택지다.</p>
</div>

<div class="space-y-12">
  <div class="p-8 glass rounded-3xl">
    <h3 class="text-3xl font-bold mb-6">📍 Month 3: 첫 난관</h3>
    <p class="text-xl leading-relaxed mb-6">비자/자격증/생활비 충격</p>
    <p class="text-2xl font-bold text-emerald-400">💡 해결: 현지 네트워킹 + 단계적 진입</p>
  </div>

  <div class="p-8 glass rounded-3xl">
    <h3 class="text-3xl font-bold mb-6">⚠️ Month ${Math.floor(months/2)}: 중간 위기</h3>
    <p class="text-xl leading-relaxed mb-6">현지 경쟁 + 가족 적응</p>
    <p class="text-2xl font-bold text-teal-400">🎯 대안: 사업 전환 + PNP 활용</p>
  </div>

  <div class="p-8 glass rounded-3xl">
    <h3 class="text-3xl font-bold mb-6">✅ Month ${months}: 완주</h3>
    <p class="text-xl leading-relaxed mb-6">${scenario.visa} 성공 → ${scenario.salary}</p>
    <p class="text-2xl font-bold text-gradient bg-gradient-to-r from-emerald-400 to-teal-500 bg-clip-text text-transparent">
      📊 성공률: ${scenario.success}% | 월 생활비 ${scenario.living}만
    </p>
  </div>
</div>

<div class="mt-16 pt-12 border-t-4 border-white/20 text-center grid grid-cols-1 md:grid-cols-2 gap-8">
  <div>
    <h4 class="text-xl font-bold mb-4">💰 예상 결과</h4>
    <div class="space-y-2 text-lg">
      <div>현재: 월 200만</div>
      <div>${goal}: 월 ${scenario.living}만 <span class="text-emerald-400">(${scenario.living > 200 ? '+' : ''}${scenario.living-200}만)</span></div>
      <div>자산 증가: +2.5억</div>
    </div>
  </div>
  <div>
    <h4 class="text-xl font-bold mb-4">🎯 다음 미션</h4>
    <div class="space-y-1 text-sm">
      <div>✅ "${goal} ${job} 2026 채용" 검색</div>
      <div>✅ "${job} ${goal} 이민 후기" 유튜브</div>
      <div>✅ "${scenario.visa} 가이드" PDF</div>
    </div>
  </div>
</div>

<div class="mt-12 pt-8 border-t border-white/20 text-center text-sm opacity-75">
  <p>희망구매플랫폼 v4.0 | 최종 업데이트 ${VIBE_DB.lastVerified} | 사례 ${VIBE_DB.scenariosCount || 27}개</p>
</div>
  `;

  // UI 업데이트
  document.getElementById('story-title').textContent = title;
  document.getElementById('progress-fill').style.width = progress + '%';
  document.getElementById('progress-text').textContent = `${progress}% ████████████████████▌░░░`;
  document.getElementById('pdf-content').innerHTML = content;

  document.getElementById('progress-section').classList.remove('hidden');
  document.getElementById('pdf-content').classList.remove('hidden');
  document.getElementById('pdf-btn').disabled = false;

  // LocalStorage 저장
  localStorage.setItem('lastStory', JSON.stringify({age, job, start, goal, months, scenario}));
}

/** PDF 다운로드 */
async function downloadPDF() {
  const { jsPDF } = window.jspdf;
  const pdf = new jsPDF('p', 'mm', 'a4');
  const element = document.getElementById('pdf-content');

  const canvas = await html2canvas(element, {
    scale: 2, backgroundColor: '#1e3a8a', useCORS: true
  });

  const imgData = canvas.toDataURL('image/png');
  const imgWidth = 210;
  const pageHeight = 295;
  let heightLeft = (canvas.height * imgWidth) / canvas.width;
  let position = 0;

  pdf.addImage(imgData, 'PNG', 0, position, imgWidth, heightLeft);
  pdf.save(`희망구매_${document.getElementById('goal').value}_${Date.now()}.pdf`);
}

/** AI 검증 시뮬레이션 (실제 배포시 제미나이 연동) */
async function aiVerifyAll() {
  // 시뮬레이션: 1.5초 후 변경사항 생성
  setTimeout(() => {
    VIBE_DB.changes.unshift({
      type: '환율',
      details: 'CAD: 1050→1080 (+2.8%)',
      timestamp: new Date().toLocaleString()
    });
    VIBE_DB.lastVerified = new Date().toLocaleString();
    showToast('✅ AI 검증 완료! 3개 변경사항 발견');
  }, 1500);
}

/** 랜덤 사례 */
function randomScenario() {
  const scenarios = [
    {age:60,job:'은퇴',start:'서울',goal:'다낭'},
    {age:53,job:'인테리어',start:'의정부',goal:'빈'},
    {age:48,job:'용접공',start:'울산',goal:'노르웨이'},
    {age:52,job:'타일공',start:'의정부',goal:'캐나다'}
  ];
  const random = scenarios[Math.floor(Math.random() * scenarios.length)];
  document.getElementById('age').value = random.age;
  document.getElementById('job').value = random.job;
  document.getElementById('start').value = random.start;
  document.getElementById('goal').value = random.goal;
  generateStory();
}

/** 외부 링크 */
function googleSearch() { window.open(`https://google.com/search?q=${document.getElementById('goal').value || '이민'} ${document.getElementById('job').value || '취업'} 후기`); }
function youtubeSearch() { window.open(`https://youtube.com/results?search_query=${document.getElementById('goal').value || '해외이주'} 현실`); }

/** 토스트 알림 */
function showToast(message) {
  const toast = document.createElement('div');
  toast.className = 'fixed top-6 right-6 bg-emerald-500/90 backdrop-blur-sm text-white px-6 py-4 rounded-2xl shadow-2xl z-50 transform translate-x-full transition-all duration-300';
  toast.textContent = message;
  document.body.appendChild(toast);
  setTimeout(() => toast.classList.remove('translate-x-full'), 100);
  setTimeout(() => toast.remove(), 4000);
}

// 초기화: 최근 사례 로드
if (localStorage.getItem('lastStory')) {
  const last = JSON.parse(localStorage.getItem('lastStory'));
  ['age','job','start','goal'].forEach(id => {
    document.getElementById(id).value = last[id];
  });
  document.getElementById('months').value = last.months;
  document.getElementById('month-label').textContent = last.months + '개월';
}
</script>
</body>
</html>

