{
  "name": "Hope Purchase Platform v4.0",
  "description": "A platform predicting costs and success probabilities for immigration, employment, and investment across different countries using AI-verified data."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ScenarioData {
  success: number;
  salary: string;
  visa: string;
  living: number;
}

export interface ScenarioDB {
  rates: { [key: string]: number };
  scenarios: { [key: string]: ScenarioData };
  lastVerified: string;
  changes: Array<{
    type: string;
    details: string;
    timestamp: string;
  }>;
}

export interface UserInput {
  age: string;
  job: string;
  start: string;
  goal: string;
  months: number;
}

export interface StoryResult {
  title: string;
  scenarioData: ScenarioData;
  progress: number;
  userInput: UserInput;
  timestamp: string;
}

import { ScenarioDB, UserInput } from './types';

export const INITIAL_DB: ScenarioDB = {
  rates: { CAD: 1080, EUR: 1540, CHF: 1620, USD: 1380 },
  scenarios: {
    // 인테리어 전문가
    '인테리어_오스트리아': { success: 72, salary: '6억원', visa: 'Red-White-Red', living: 195 },
    '인테리어_독일': { success: 67, salary: '8.8억원', visa: 'Blue Card', living: 240 },
    '인테리어_스위스': { success: 45, salary: '13.5억원', visa: '프리랜서', living: 380 },

    // 기술직
    '용접공_노르웨이': { success: 65, salary: '13억원', visa: '北海 계약직', living: 420 },
