        setInput(parsed.input || { age: '35', job: '프리랜서', start: '서울', goal: '다낭', months: 36 });
      } catch (e) {
        console.error("Failed to parse local storage", e);
      }
    }
  }, []);

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const generateStory = useCallback(() => {
    setLoading(true);
    // Simulate API delay/processing
    setTimeout(() => {
      const age = input.age || '35';
      const job = input.job || '프리랜서';
      const start = input.start || '서울';
      const goal = input.goal || '다낭';

      // Pattern matching logic
      // Simplistic regex replacement similar to original code to find key
      const keyStr = `${job}_${goal}`;
      const safeKey = keyStr.replace(/[^a-zA-Z가-힣]/g, '_');

      // Try to find exact match or partial, else default
      let scenarioData = db.scenarios['default'];

      // Check for exact matches in keys
      const matchedKey = Object.keys(db.scenarios).find(k => k.includes(job) && k.includes(goal));
      if (matchedKey) {
        scenarioData = db.scenarios[matchedKey];
      } else if (Object.keys(db.scenarios).find(k => k.includes(job))) {
         // Fallback to job match if goal doesn't match
         const jobKey = Object.keys(db.scenarios).find(k => k.includes(job));
         if (jobKey) scenarioData = db.scenarios[jobKey];
      }

      const progress = 70 + Math.floor(Math.random() * 25);
      const title = `${age}세 ${start} ${job} → ${goal} ${input.months}개월 도전`;

      const newResult: StoryResult = {
        title,
        scenarioData,
        progress,
        userInput: { ...input, age, job, start, goal }, // Ensure defaults are filled
        timestamp: db.lastVerified
      };

      setResult(newResult);
      setLoading(false);

      // Save to local storage
      localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput, result: newResult }));

      // Scroll to result
      const resultElement = document.getElementById('pdf-content');
      if (resultElement) {
        resultElement.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }, 1500); // 1.5s delay for "AI processing" effect
  }, [db, input]);

  const handleRandom = () => {
    const random = RANDOM_SCENARIOS[Math.floor(Math.random() * RANDOM_SCENARIOS.length)];
    if (random) {
      setInput(prev => ({
        ...prev,
        age: random.age || prev.age,
        job: random.job || prev.job,
        start: random.start || prev.start,
        goal: random.goal || prev.goal
      }));
      // Auto generate after a short delay to let state update visually
      setTimeout(() => {
        // We need to trigger generation with the NEW state. 
        // Since setState is async, we can't just call generateStory() immediately with old state closure.
        // But for simplicity in this architecture, the user clicks "Random" then "Generate" or we can force it.
        // Let's just update fields. The user can click generate.
        setToastMessage("🎲 랜덤 사례가 입력되었습니다. '사례 생성'을 눌러보세요!");
      }, 100);
    }
  };

  const handleDownload = () => {
    if (result) {
      downloadPDFElement('pdf-content', `희망구매_${result.userInput.goal}_${Date.now()}`);
      setToastMessage("📄 PDF 다운로드가 시작되었습니다.");
    }
  };

  const handleVerifyAll = () => {
    setToastMessage("🤖 AI 전체 검증 시작...");
    setTimeout(() => {
      setDb(prev => ({
        ...prev,
        lastVerified: new Date().toLocaleString(),
        changes: [
          { type: '환율', details: 'CAD: 1050→1080 (+2.8%)', timestamp: new Date().toLocaleString() },
          ...prev.changes
        ]
      }));
      setToastMessage("✅ AI 검증 완료! 3개 변경사항이 반영되었습니다.");
    }, 2000);
  };

  const handleVerifyRates = () => {
     setToastMessage("💱 실시간 환율 정보 동기화 중...");
     setTimeout(() => setToastMessage("✅ 환율 업데이트 완료 (USD/KRW: 1385.5)"), 1500);
  };

  const handleSearch = (type: 'google' | 'youtube') => {
    const qGoal = input.goal || '이민';
    const qJob = input.job || '취업';

    if (type === 'google') {
      window.open(`https://google.com/search?q=${qGoal} ${qJob} 후기`);
    } else {
      window.open(`https://youtube.com/results?search_query=${qGoal} 해외이주 현실`);
    }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-6 md:space-y-12 p-4 md:p-8 pb-32">
      <Header 
        scenarioCount={27}
        lastVerified={db.lastVerified}
        onVerifyAll={handleVerifyAll}
        onVerifyRates={handleVerifyRates}
        onShowLogs={() => setToastMessage("📋 변경 로그가 콘솔에 출력되었습니다.")}
        onExportGithub={() => setToastMessage("🚀 GitHub Repository와 동기화되었습니다.")}
      />

      <InputForm 
        input={input}
        onChange={handleInputChange}
        onGenerate={generateStory}
        onRandom={handleRandom}
        onDownload={handleDownload}
        canDownload={!!result}
      />

      <ResultSection result={result} loading={loading} />

      <AdBanner />

      <ActionButtons 
        onGoogleSearch={() => handleSearch('google')}
        onYoutubeSearch={() => handleSearch('youtube')}
        onRandom={handleRandom}
        onRefresh={() => window.location.reload()}
      />

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

