import React, { useState, useEffect } from 'react';
import { GlassCard } from './GlassCard';
import { UserInput } from '../types';
import { INITIAL_DB, RANDOM_SCENARIOS } from '../constants';

interface InputFormProps {
  input: UserInput;
  onChange: (field: keyof UserInput, value: string | number) => void;
  onGenerate: () => void;
  onRandom: () => void;
  onDownload: () => void;
  canDownload: boolean;
}

export const InputForm: React.FC<InputFormProps> = ({
  input,
  onChange,
  onGenerate,
  onRandom,
  onDownload,
  canDownload
}) => {
  const [prompt, setPrompt] = useState('');
  const [isanalyzing, setIsAnalyzing] = useState(false);

  // Helper: Extract data from text
  const parseAndSet = (text: string) => {
    setIsAnalyzing(true);
    let newAge = '';
    let newJob = '';
    let newStart = '';
    let newGoal = '';
    let newMonths = 36;

    // 1. Regex Extraction
    const ageMatch = text.match(/(\d+)(?:세|살|age)/);
    if (ageMatch) newAge = ageMatch[1];

    const monthMatch = text.match(/(\d+)(?:개월|달|month)/);
    if (monthMatch) newMonths = parseInt(monthMatch[1], 10);

    const startMatch = text.match(/([가-힣]+)(?:에서| 살고| 거주)/);
    if (startMatch) newStart = startMatch[1];

    // 2. Keyword Matching against DB
    const dbKeys = Object.keys(INITIAL_DB.scenarios);
    const jobs = new Set<string>();
    const countries = new Set<string>();

    dbKeys.forEach(key => {
      const [j, c] = key.split('_');
      if (j && j !== 'default') jobs.add(j);
      if (c) countries.add(c);
    });

    // Check for Job matches
    Array.from(jobs).forEach(j => {
      if (text.includes(j)) newJob = j;
    });

    // Check for Country matches
    Array.from(countries).forEach(c => {
      if (text.includes(c)) newGoal = c;
    });

    // 3. Fallback / Gap Filling Logic
    // If Goal is found but Job is missing, find a job that works for that goal
    if (newGoal && !newJob) {
      const possibleJobs = dbKeys
        .filter(k => k.includes(newGoal))
        .map(k => k.split('_')[0])
        .filter(j => j !== 'default');
      if (possibleJobs.length > 0) {
        newJob = possibleJobs[Math.floor(Math.random() * possibleJobs.length)];
      } else {
        newJob = '프리랜서'; // Default
      }
    }

    // If nothing found, pick completely random
    if (!newGoal && !newJob && !newAge) {
      const random = RANDOM_SCENARIOS[Math.floor(Math.random() * RANDOM_SCENARIOS.length)];
      newAge = random.age || '35';
      newJob = random.job || '디지털노마드';
      newStart = random.start || '서울';
      newGoal = random.goal || '발리';
    }

    // Default values for remaining gaps
    if (!newAge) newAge = (Math.floor(Math.random() * 30) + 25).toString();
    if (!newStart) newStart = '서울';
    if (!newGoal) newGoal = '해외';
    if (!newJob) newJob = '회사원';

    // Update Parent State
    onChange('age', newAge);
    onChange('job', newJob);
    onChange('start', newStart);
    onChange('goal', newGoal);
    onChange('months', newMonths);

    setIsAnalyzing(false);
  };

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setPrompt(e.target.value);
  };

  const handleDirectGenerate = () => {
    // If prompt is empty, trigger random
    if (!prompt.trim()) {
      onRandom();
      setTimeout(onGenerate, 100);
      return;
    }
    parseAndSet(prompt);
    setTimeout(onGenerate, 200); // Allow state to update
  };

  return (
    <GlassCard className="p-6 md:p-8 space-y-6 relative overflow-hidden">

      {/* AI Ribbon */}
      <div className="absolute top-0 right-0 bg-emerald-500 text-xs font-bold px-3 py-1 rounded-bl-xl shadow-lg z-10 text-white">
        AI NLP Enabled
      </div>

      <div className="space-y-4">
        <label className="text-emerald-300 font-bold text-lg flex items-center gap-2">
          <span>💬 AI 시뮬레이션 프롬프트</span>
        </label>
        <div className="relative">
          <textarea
            value={prompt}
            onChange={handlePromptChange}
            className="w-full p-6 bg-black/20 rounded-3xl text-lg md:text-xl font-medium placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-emerald-500/50 border border-white/10 transition-all resize-none h-40"
            placeholder="자유롭게 이야기해주세요. &#13;&#10;예) 의정부 사는 53세 인테리어 업자인데 오스트리아 빈으로 가고 싶어. &#13;&#10;예) 29세 간호사 미국 이민 방법 알려줘."
          />
          <div className="absolute bottom-4 right-4">
            <button 
              onClick={() => parseAndSet(prompt)}
              className="text-xs bg-white/10 hover:bg-white/20 px-3 py-1 rounded-full transition-all text-emerald-200"
            >
              🔄 분석하기
            </button>
          </div>
        </div>
      </div>

      {/* Detected Tags (Visual Feedback) */}
      <div className="flex flex-wrap gap-2 items-center justify-center bg-white/5 p-4 rounded-2xl border border-white/5 min-h-[80px]">
        {input.age ? (
          <>
            <span className="bg-indigo-500/40 border border-indigo-400/30 px-3 py-1 rounded-full text-sm">👤 {input.age}세</span>
            <span className="bg-blue-500/40 border border-blue-400/30 px-3 py-1 rounded-full text-sm">📍 {input.start} 출발</span>
            <span className="bg-emerald-500/40 border border-emerald-400/30 px-3 py-1 rounded-full text-sm">💼 {input.job}</span>
            <span className="text-white/30">→</span>
            <span className="bg-purple-500/40 border border-purple-400/30 px-3 py-1 rounded-full text-sm font-bold">🎯 {input.goal}</span>
            <span className="bg-pink-500/40 border border-pink-400/30 px-3 py-1 rounded-full text-sm">🕒 {input.months}개월</span>
          </>
        ) : (
          <span className="text-white/30 text-sm animate-pulse">프롬프트를 입력하면 AI가 자동으로 핵심 정보를 추출합니다...</span>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-2">
        <button 
          onClick={handleDirectGenerate}
          className="bg-gradient-to-r from-emerald-500 via-teal-500 to-emerald-600 hover:from-emerald-600 p-4 md:p-6 rounded-3xl text-lg md:text-xl font-black shadow-xl hover:shadow-2xl hover:scale-[1.02] transition-all active:scale-95 flex items-center justify-center gap-2 group"
        >
          <span className="group-hover:animate-spin">✨</span> 시나리오 생성
        </button>
        <button 
          onClick={onDownload}
          disabled={!canDownload}
          className={`bg-gradient-to-r from-purple-500 via-pink-500 to-purple-600 p-4 md:p-6 rounded-3xl text-lg md:text-xl font-black shadow-xl transition-all ${!canDownload ? 'opacity-50 cursor-not-allowed grayscale' : 'hover:from-purple-600 hover:shadow-2xl hover:scale-[1.02] active:scale-95'}`}
        >
          📄 PDF 다운로드
        </button>
        <button 
          onClick={onRandom}
          className="bg-gradient-to-r from-orange-500 via-red-500 to-orange-600 hover:from-orange-600 p-4 md:p-6 rounded-3xl text-lg md:text-xl font-bold shadow-xl hover:shadow-2xl hover:scale-[1.02] transition-all active:scale-95"
        >
          🎲 랜덤 사례
        </button>
      </div>
    </GlassCard>
  );
};

