export const detectCountry = (text: string): string => {
  const t = text.toLowerCase();
  for (const [key, config] of Object.entries(GLOBAL_100)) {
    // Check country name key
    if (t.includes(key)) return key;
    // Check city names
    if (config.cities.some(city => t.includes(city.toLowerCase()))) return key;
    // Special mapping (Korean names)
    if (key === 'korea' && /한국|서울|강남/.test(t)) return key;
    if (key === 'japan' && /일본|도쿄|오사카/.test(t)) return key;
    if (key === 'usa' && /미국|아메리카/.test(t)) return key;
    if (key === 'uk' && /영국|런던/.test(t)) return key;
    if (key === 'germany' && /독일|베를린/.test(t)) return key;
    if (key === 'vietnam' && /베트남|다낭/.test(t)) return key;
    if (key === 'china' && /중국|상해/.test(t)) return key;
    if (key === 'thailand' && /태국|방콕/.test(t)) return key;
    if (key === 'austria' && /오스트리아|빈/.test(t)) return key;
    if (key === 'switzerland' && /스위스|취리히/.test(t)) return key;
    if (key === 'canada' && /캐나다|밴쿠버/.test(t)) return key;
    if (key === 'australia' && /호주|시드니/.test(t)) return key;
    if (key === 'uae' && /두바이|아랍/.test(t)) return key;
  }
  return 'default';
};

