export interface StoryStage {
  month: number;
  title: string;
  desc: string;
  highlight: string;
}

export interface ComparisonRow {
  item: string;
  before: string;
  after: string;
  diff: string;
}

export interface ScenarioData {
  success: number;
  salary: string;
  visa: string;
  living: number;
  story?: {
    day1?: {
      title: string;
      thought: string;
      action: string;
    };
    initial: StoryStage;
    mid: StoryStage;
    final: StoryStage;
  };
