  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Helper: Extract data from text
  const parseAndSet = (text: string) => {
    setIsAnalyzing(true);
    let newAge = '';
    let newJob = '';
    let newStart = '';
    let newGoal = '';
    let newMonths = 36;

    // 1. Regex Extraction
    const ageMatch = text.match(/(\d+)(?:세|살|age)/);
    if (ageMatch) newAge = ageMatch[1];

    const monthMatch = text.match(/(\d+)(?:개월|달|month)/);
    if (monthMatch) newMonths = parseInt(monthMatch[1], 10);

    const startMatch = text.match(/([가-힣]+)(?:에서| 살고| 거주)/);
    if (startMatch) newStart = startMatch[1];

    // 2. Keyword Matching against DB
    const dbKeys = Object.keys(INITIAL_DB.scenarios);
    const jobs = new Set<string>();
    const countries = new Set<string>();

    dbKeys.forEach(key => {
      const [j, c] = key.split('_');
      if (j && j !== 'default') jobs.add(j);
      if (c) countries.add(c);
    });

    // Check for Job matches
    Array.from(jobs).forEach(j => {
      if (text.includes(j)) newJob = j;
    });

    // Check for Country matches
    Array.from(countries).forEach(c => {
      if (text.includes(c)) newGoal = c;
    });

    // 3. Fallback / Gap Filling Logic
    if (newGoal && !newJob) {
      const possibleJobs = dbKeys
        .filter(k => k.includes(newGoal))
        .map(k => k.split('_')[0])
        .filter(j => j !== 'default');
      if (possibleJobs.length > 0) {
        newJob = possibleJobs[Math.floor(Math.random() * possibleJobs.length)];
      } else {
        newJob = '프리랜서'; // Default
      }
    }

    // Update Parent State
    if(newAge) onChange('age', newAge);
    if(newJob) onChange('job', newJob);
    if(newStart) onChange('start', newStart);
    if(newGoal) onChange('goal', newGoal);
    onChange('months', newMonths);

    setIsAnalyzing(false);
  };

  const handlePromptChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setPrompt(e.target.value);
  };

  const handleDirectGenerate = () => {
    // If prompt is empty, trigger random
    if (!prompt.trim() && !input.goal) {
      onRandom();
      setTimeout(onGenerate, 100);
      return;
    }
    if (prompt.trim()) {
        parseAndSet(prompt);
        setTimeout(onGenerate, 200);
    } else {
        onGenerate();
    }
  };

  return (
    <GlassCard className="p-6 md:p-8 space-y-6 relative overflow-hidden">

      {/* AI Ribbon */}
      <div className="absolute top-0 right-0 bg-emerald-500 text-xs font-bold px-3 py-1 rounded-bl-xl shadow-lg z-10 text-white">
        Global 100 Countries Supported
      </div>

      <div className="space-y-4">
        <label className="text-emerald-300 font-bold text-lg flex items-center gap-2">
          <span>🌍 글로벌 설정 (100개국 자동 지원)</span>
        </label>

        {/* Country Selector */}
        <select 
            className="w-full p-4 bg-white/10 rounded-2xl text-lg font-bold border border-white/10 focus:outline-none focus:ring-2 focus:ring-emerald-500/50 text-white [&>option]:text-black"
            value={input.country || ''}
            onChange={(e) => onChange('country', e.target.value)}
        >
            <option value="">🗺️ 국가/도시 선택 (자동 감지)</option>
            {Object.entries(GLOBAL_100).map(([key, config]) => (
                <option key={key} value={key}>
                    {config.currency === '₩' ? '🇰🇷' : config.currency === '¥' ? '🇯🇵' : config.currency === '€' ? '🇪🇺' : config.currency === '$' ? '🇺🇸' : '🌍'} {key.toUpperCase()} ({config.cities[0]})
                </option>
            ))}
        </select>

        <div className="grid grid-cols-2 gap-4">
            <input 
                placeholder="나이 (예: 53)" 
                value={input.age} 
                onChange={(e) => onChange('age', e.target.value)}
                className="p-4 bg-black/20 rounded-2xl text-center border border-white/10"
            />
            <input 
                placeholder="목표 도시 (예: 시부야)" 
                value={input.goal} 
                onChange={(e) => onChange('goal', e.target.value)}
                className="p-4 bg-black/20 rounded-2xl text-center border border-white/10"
            />
        </div>

        <label className="text-emerald-300 font-bold text-lg flex items-center gap-2 mt-4">
          <span>💬 AI 시뮬레이션 프롬프트 (선택)</span>
        </label>
        <div className="relative">
          <textarea
            value={prompt}
            onChange={handlePromptChange}
            className="w-full p-6 bg-black/20 rounded-3xl text-lg md:text-xl font-medium placeholder-white/30 focus:outline-none focus:ring-2 focus:ring-emerald-500/50 border border-white/10 transition-all resize-none h-32"
            placeholder="예) 53세 의정부 인테리어 업자인데 오스트리아 빈으로 가고 싶어. &#13;&#10;예) 29세 간호사 미국 이민 방법 알려줘."
          />
          <div className="absolute bottom-4 right-4">
            <button 
              onClick={() => parseAndSet(prompt)}
              className="text-xs bg-white/10 hover:bg-white/20 px-3 py-1 rounded-full transition-all text-emerald-200"
            >
              🔄 분석하기
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-2">
        <button 
          onClick={handleDirectGenerate}
          className="bg-gradient-to-r from-emerald-500 via-teal-500 to-emerald-600 hover:from-emerald-600 p-4 md:p-6 rounded-3xl text-lg md:text-xl font-black shadow-xl hover:shadow-2xl hover:scale-[1.02] transition-all active:scale-95 flex items-center justify-center gap-2 group"
        >
          <span className="group-hover:animate-spin">🌍</span> 글로벌 여정 생성
        </button>
        <button 
          onClick={onDownload}
          disabled={!canDownload}
          className={`bg-gradient-to-r from-purple-500 via-pink-500 to-purple-600 p-4 md:p-6 rounded-3xl text-lg md:text-xl font-black shadow-xl transition-all ${!canDownload ? 'opacity-50 cursor-not-allowed grayscale' : 'hover:from-purple-600 hover:shadow-2xl hover:scale-[1.02] active:scale-95'}`}
        >
          📄 PDF 다운로드
        </button>
        <button 
          onClick={onRandom}
          className="bg-gradient-to-r from-orange-500 via-red-500 to-orange-600 hover:from-orange-600 p-4 md:p-6 rounded-3xl text-lg md:text-xl font-bold shadow-xl hover:shadow-2xl hover:scale-[1.02] transition-all active:scale-95"
        >
          🎲 랜덤 사례
        </button>
      </div>
    </GlassCard>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { InputForm } from './components/InputForm';
import { ResultSection, downloadPDFElement } from './components/ResultSection';
import { AdBanner } from './components/AdBanner';
import { ActionButtons } from './components/ActionButtons';
import { Toast } from './components/Toast';
import { AdminDashboard } from './components/AdminDashboard';
import { INITIAL_DB, RANDOM_SCENARIOS, GLOBAL_100, detectCountry } from './constants';
import { UserInput, StoryResult, ScenarioDB, ScenarioData } from './types';
import { GlassCard } from './components/GlassCard';

function App() {
  const [db, setDb] = useState<ScenarioDB>(INITIAL_DB);
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  const [input, setInput] = useState<UserInput>({
    age: '',
    job: '',
    start: '',
    goal: '',
    months: 36,
    country: ''
  });
  const [result, setResult] = useState<StoryResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // Check for admin hash on load
  useEffect(() => {
    if (window.location.hash === '#admin') {
      setShowAdminLogin(true);
    }

    // Load local storage
    const lastStory = localStorage.getItem('lastStory');
    if (lastStory) {
      try {
        const parsed = JSON.parse(lastStory);
        setInput(parsed.input || { age: '35', job: '프리랜서', start: '서울', goal: '다낭', months: 36 });
      } catch (e) {
        console.error("Failed to parse local storage", e);
      }
    }
  }, []);

  const handleAdminLogin = () => {
    if (adminPassword === '1234') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setToastMessage("🔓 관리자 모드로 접속했습니다.");
    } else {
      alert("비밀번호가 올바르지 않습니다.");
    }
  };

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const generateStory = useCallback(() => {
    setLoading(true);

    setTimeout(() => {
      const age = input.age || '35';
      const job = input.job || '프리랜서';
      const start = input.start || '서울';
      const goal = input.goal || '해외';

      // 1. Try to find a specific hardcoded scenario
      let scenarioData: ScenarioData | null = null;
      let matchScore = 0;
      let bestKey = '';

      const j = job.replace(/\s/g, '');
      const g = goal.replace(/\s/g, '');

      Object.keys(db.scenarios).forEach(key => {
        let score = 0;
        const [kJob, kCountry] = key.split('_');

        if (kJob && j.includes(kJob)) score += 3;
        if (kCountry && g.includes(kCountry)) score += 3;

        // Fallback matching
        if (kCountry === '동남아' && ['베트남','태국','말레이시아'].some(c => g.includes(c))) score += 2;

        if (score > matchScore) {
          matchScore = score;
          scenarioData = db.scenarios[key];
          bestKey = key;
        }
      });

      // 2. If no strong match (score < 3), generate dynamic story using GLOBAL_100
      if (!scenarioData || matchScore < 3) {
        console.log("Using Global Auto-Generation Engine");

        const countryKey = input.country || detectCountry(goal);
        const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];

        // Dynamic Story Generation
        scenarioData = {
            success: 70 + Math.floor(Math.random() * 25),
            salary: config.avgSalary,
            visa: config.visaName,
            living: Math.floor(Math.random() * 200) + 150, // Mock living cost
            story: {
                day1: {
                    title: `${goal}은 ${config.currency}화폐권의 꿈이다`,
                    thought: `${start}의 경쟁을 넘어 ${goal}에서 ${config.currency} 소득을 창출한다.`,
                    action: `${config.prop} 앱 설치 및 ${config.bank} 계좌 개설 정보 검색.`
                },
                initial: {
                    month: 3,
                    title: '초기 정착의 난관',
                    desc: `언어 장벽과 초기 생활비(${config.currency} 기준)가 예상보다 20% 초과. ${config.prop}을 통해 저렴한 거주지 확보 시도.`,
                    highlight: `절약: 현지 ${config.bank} 카드로 수수료 절감`
                },
                mid: {
                    month: Math.floor(input.months / 2),
                    title: '비자 및 적응 위기',
                    desc: `${config.visaName} 갱신/취득 조건이 까다로워짐. 현지 네트워크 부족으로 고립감 심화.`,
                    highlight: `전략: 한인 커뮤니티 및 현지 모임 참여`
                },
                final: {
                    month: input.months,
                    title: '현지화 완료',
                    desc: `${goal}에서의 삶이 안정화됨. ${config.currency} 기반의 경제적 자유 초석 마련.`,
                    highlight: `자산: ${config.currency} 수익원 확보`
                }
            },
            resultTable: [
                { item: '화폐', before: 'KRW (₩)', after: `${config.code.toUpperCase()} (${config.currency})`, diff: '환전 필요' },
                { item: '주거', before: '한국 아파트', after: `${goal} 현지 주택`, diff: `${config.prop} 이용` },
                { item: '비자', before: '한국 국적', after: config.visaName, diff: '취득 완료' },
                { item: '은행', before: '국내 은행', after: config.bank, diff: '계좌 개설' }
            ],
            additionalInfo: {
                obstacles: ['현지 언어 장벽', `${config.visaName} 발급 까다로움`, '초기 정착금 부족'],
                alternatives: ['어학연수 후 취업', '워킹홀리데이 활용', '현지 법인 취업'],
                nextSteps: {
                    google: `${goal} ${config.visaName} 조건`,
                    youtube: `${goal} 이민 현실 브이로그`,
                    pdf: `${config.code.toUpperCase()} 비자 가이드북`
                }
            }
        };
      }

      console.log(`Matched: ${bestKey || 'Dynamic Global'} (Score: ${matchScore})`);

      const scenarioMonths = scenarioData.story?.final.month;
      const finalMonths = scenarioMonths || input.months;
      const progress = 70 + Math.floor(Math.random() * 25);
      const title = `${age}세 ${start} ${job} → ${goal} ${finalMonths}개월 여정`;

      const newResult: StoryResult = {
        title,
        scenarioData,
        progress,
        userInput: { ...input, age, job, start, goal, months: finalMonths },
        timestamp: db.lastVerified
      };

      setResult(newResult);
      setLoading(false);

      localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput, result: newResult }));

      setTimeout(() => {
        document.getElementById('pdf-content')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);

    }, 1200); 
  }, [db, input]);

  const handleRandom = () => {
    const random = RANDOM_SCENARIOS[Math.floor(Math.random() * RANDOM_SCENARIOS.length)];
    if (random) {
      setInput(prev => ({ ...prev, ...random, country: '' }));
      setToastMessage("🎲 랜덤 사례가 입력되었습니다. '사례 생성'을 눌러보세요!");
    }
  };

  const handleDownload = () => {
    if (result) {
      downloadPDFElement('pdf-content', `희망구매_${result.userInput.goal}_${Date.now()}`);
      setToastMessage("📄 PDF 다운로드가 시작되었습니다.");
    }
  };

  const handleSearch = (type: 'google' | 'youtube') => {
    const qGoal = input.goal || '이민';
    const qJob = input.job || '취업';
    const url = type === 'google' 
      ? `https://google.com/search?q=${qGoal} ${qJob} 현실 후기`
      : `https://youtube.com/results?search_query=${qGoal} ${qJob} 브이로그`;
    window.open(url);
  };

  // --- Admin Login Modal ---
  if (showAdminLogin) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-900 p-4">
        <GlassCard className="p-8 w-full max-w-md text-center space-y-6">
          <h2 className="text-2xl font-bold">🛡️ 관리자 로그인</h2>
          <input 
            type="password" 
            value={adminPassword}
            onChange={(e) => setAdminPassword(e.target.value)}
            className="w-full p-4 bg-white/10 rounded-xl text-center text-xl font-bold focus:outline-none focus:ring-2 focus:ring-emerald-500"
            placeholder="비밀번호 입력 (1234)"
            onKeyDown={(e) => e.key === 'Enter' && handleAdminLogin()}
          />
          <div className="flex gap-4">
            <button onClick={() => setShowAdminLogin(false)} className="flex-1 py-3 rounded-xl bg-gray-600 hover:bg-gray-500 font-bold">취소</button>
            <button onClick={handleAdminLogin} className="flex-1 py-3 rounded-xl bg-emerald-600 hover:bg-emerald-500 font-bold">접속</button>
          </div>
        </GlassCard>
      </div>
    );
  }

  // --- Admin Dashboard View ---
  if (isAdmin) {
    return (
      <AdminDashboard 
        db={db} 
        onUpdateDb={setDb} 
        onClose={() => setIsAdmin(false)} 
      />
    );
  }

  // --- Main User View ---
  return (
    <div className="max-w-5xl mx-auto space-y-6 md:space-y-12 p-4 md:p-8 pb-32">
      <Header 
        scenarioCount={Object.keys(db.scenarios).length}
        lastVerified={db.lastVerified}
      />

      <InputForm 
        input={input}
        onChange={handleInputChange}
        onGenerate={generateStory}
        onRandom={handleRandom}
        onDownload={handleDownload}
        canDownload={!!result}
      />

      <ResultSection result={result} loading={loading} />

      <AdBanner />

      <ActionButtons 
        onGoogleSearch={() => handleSearch('google')}
        onYoutubeSearch={() => handleSearch('youtube')}
        onRandom={handleRandom}
        onRefresh={() => window.location.reload()}
      />

      {/* Admin Link Footer */}
      <div className="text-center opacity-30 hover:opacity-100 transition-opacity">
        <button onClick={() => setShowAdminLogin(true)} className="text-xs">🔒 관리자 접속</button>
      </div>

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

