import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { InputForm } from './components/InputForm';
import { ResultSection, downloadPDFElement } from './components/ResultSection';
import { AdBanner } from './components/AdBanner';
import { ActionButtons } from './components/ActionButtons';
import { Toast } from './components/Toast';
import { AdminDashboard } from './components/AdminDashboard';
import { INITIAL_DB, RANDOM_SCENARIOS, GLOBAL_100, detectCountry, DRY_WRITER_VARS } from './constants';
import { UserInput, StoryResult, ScenarioDB, ScenarioData } from './types';
import { GlassCard } from './components/GlassCard';

function App() {
  const [db, setDb] = useState<ScenarioDB>(INITIAL_DB);
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  const [input, setInput] = useState<UserInput>({
    age: '',
    job: '',
    start: '',
    goal: '',
    months: 36,
    country: ''
  });
  const [result, setResult] = useState<StoryResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [credits, setCredits] = useState<number>(25);

  // Load state on start
  useEffect(() => {
    if (window.location.hash === '#admin') setShowAdminLogin(true);

    const savedCredits = localStorage.getItem('credits');
    if (savedCredits) setCredits(parseInt(savedCredits, 10));

    const lastStory = localStorage.getItem('lastStory');
    if (lastStory) {
      try {
        const parsed = JSON.parse(lastStory);
        setInput(parsed.input || { age: '53', job: '프리랜서', start: '의정부', goal: '강남', months: 18 });
        // Optionally load result, but better to let user generate fresh to use credits/randomness
      } catch (e) { console.error(e); }
    }
  }, []);

  // Persist credits
  useEffect(() => {
    localStorage.setItem('credits', credits.toString());
  }, [credits]);

  const handleAdminLogin = () => {
    if (adminPassword === '1234') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setToastMessage("🔓 관리자 모드로 접속했습니다.");
    } else {
      alert("비밀번호가 올바르지 않습니다.");
    }
  };

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const handleReward = () => {
    setToastMessage("⏳ 광고 시청 중... (30초)");
    setTimeout(() => {
        setCredits(prev => prev + 5);
        setToastMessage("🎁 크레딧 +5 지급 완료!");
    }, 2000); // Simulated 2s for UX, prompt said 30s but we simulate fast
  };

  const generateStory = useCallback(() => {
    if (credits <= 0) {
        setToastMessage("⚠️ 크레딧이 부족합니다. 하단 리워드 버튼을 눌러주세요.");
        return;
    }

    setLoading(true);
    setCredits(prev => prev - 1); // Deduct credit

    setTimeout(() => {
      const age = input.age || '53';
      const job = input.job || '자영업';
      const start = input.start || '의정부';
      const goal = input.goal || '강남';
      const months = input.months || 18;

      // --- DRY WRITER ENGINE ---
      const countryKey = input.country || detectCountry(goal);
      const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];

      // Random Helpers
      const pick = (arr: string[]) => arr[Math.floor(Math.random() * arr.length)];
      const randInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

      const religion = pick(DRY_WRITER_VARS.religions);
      const obstacle1 = pick(DRY_WRITER_VARS.obstacles1);
      const failure1 = pick(DRY_WRITER_VARS.failures1);
      const obstacle2 = pick(DRY_WRITER_VARS.obstacles2);
      const solution = pick(DRY_WRITER_VARS.solutions);
      const conclusion = pick(DRY_WRITER_VARS.conclusions);
      const expense = pick(DRY_WRITER_VARS.expenses);

      const scenarioData: ScenarioData = {
          success: randInt(60, 95),
          salary: config.avgSalary,
          visa: config.visaName,
          living: randInt(150, 400),
          story: {
              day1: {
                  title: `${goal}는 ${religion}이다`,
                  thought: `나이 ${age}세, ${start}를 떠나 ${goal}로 향하는 것은 미친 짓일까?`,
                  action: `${config.prop} 앱을 켜고 보증금을 확인한다.`
              },
              initial: {
                  month: 3,
                  title: `${obstacle1} 발생`,
                  desc: `실패: ${failure1} | ${config.currency} 생활비 부족으로 패닉.`,
                  highlight: `${randInt(15, 30)}% 진행`
              },
              mid: {
                  month: 8,
                  title: `${obstacle2} 돌파`,
                  desc: `해결: ${solution} | ${config.bank} 대출 심사 재신청.`,
                  highlight: `${randInt(45, 60)}% 진행`
              },
              final: {
                  month: months,
                  title: conclusion,
                  desc: `하지만: 하루 ${expense}${config.currency === '₩' ? '만 원' : config.currency}씩 숨만 쉬어도 나간다...`,
                  highlight: `${randInt(80, 99)}% 완료`
              }
          },
          resultTable: [
              { item: '주거', before: `${start} 자가`, after: `${goal} 월세`, diff: '하향지원' },
              { item: '자산', before: '현상유지', after: '감소 추세', diff: `-${randInt(1,5)}천만` },
              { item: '심리', before: '불안', after: '해탈', diff: '적응완료' }
          ],
          additionalInfo: {
              obstacles: [obstacle1, obstacle2, '고독사 공포'],
              alternatives: ['고향 리턴', '기술직 전향', '야간 대리운전'],
              nextSteps: {
                  google: `${goal} ${job} 현실`,
                  youtube: `${age}세 ${goal} 이민 브이로그`,
                  pdf: `${config.code.toUpperCase()} 생존 가이드`
              }
          }
      };

      const title = `${age}세 ${start} → ${goal} ${months}개월 여정`;
      const progress = randInt(20, 85);

      const newResult: StoryResult = {
        title,
        scenarioData,
        progress,
        userInput: { ...input, age, job, start, goal, months },
        timestamp: new Date().toLocaleTimeString()
      };

      setResult(newResult);
      setLoading(false);

      localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput }));

      setTimeout(() => {
        document.getElementById('pdf-content')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);

    }, 800); // Faster generation 0.8s
  }, [input, credits]);

  const handleRandom = () => {
    const random = RANDOM_SCENARIOS[Math.floor(Math.random() * RANDOM_SCENARIOS.length)];
    if (random) {
      setInput(prev => ({ ...prev, ...random, country: '' }));
      // Auto generate for instant feel?
      // setTimeout(generateStory, 100); // Optional: Instant trigger
      setToastMessage("🎲 랜덤 변수가 설정되었습니다.");
    }
  };

  const handleDownload = () => {
    if (result) {
      downloadPDFElement('pdf-content', `희망구매_${result.userInput.goal}_${Date.now()}`);
      setToastMessage("📄 PDF 다운로드 시작...");
    }
  };

  const handleSearch = (type: 'google' | 'youtube') => {
    const qGoal = input.goal || '이민';
    const qJob = input.job || '취업';
    const url = type === 'google' 
      ? `https://google.com/search?q=${qGoal} ${qJob} 현실 후기`
      : `https://youtube.com/results?search_query=${qGoal} ${qJob} 브이로그`;
    window.open(url);
  };

  // --- Render ---
  return (
    <div className="max-w-md mx-auto min-h-screen bg-gray-900 text-white overflow-hidden pb-32 md:max-w-2xl md:pb-12">
       {/* Mobile First Wrapper */}

      <div className="p-4 space-y-6">
        <Header 
          scenarioCount={credits} // Reuse prop for credits
          lastVerified={db.lastVerified}
        />

        <InputForm 
          input={input}
          onChange={handleInputChange}
          onGenerate={generateStory}
          onRandom={handleRandom}
          onDownload={handleDownload}
          canDownload={!!result}
        />

        <ResultSection result={result} loading={loading} />

        <AdBanner onReward={handleReward} />

        <ActionButtons 
          onGoogleSearch={() => handleSearch('google')}
          onYoutubeSearch={() => handleSearch('youtube')}
          onRandom={handleRandom}
          onRefresh={() => window.location.reload()}
          onReward={handleReward}
        />
      </div>

      {showAdminLogin && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
            <GlassCard className="p-8 w-full max-w-sm text-center space-y-6">
              <h2 className="text-2xl font-bold">🛡️ 관리자</h2>
              <input 
                type="password" 
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                className="w-full p-4 bg-white/10 rounded-xl text-center text-xl font-bold"
                placeholder="Password"
              />
              <div className="flex gap-4">
                <button onClick={() => setShowAdminLogin(false)} className="flex-1 py-3 bg-gray-600 rounded-xl">취소</button>
                <button onClick={handleAdminLogin} className="flex-1 py-3 bg-emerald-600 rounded-xl">접속</button>
              </div>
            </GlassCard>
          </div>
      )}

      {isAdmin && <AdminDashboard db={db} onUpdateDb={setDb} onClose={() => setIsAdmin(false)} />}

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

