import React, { useState, useEffect } from 'react';
import { GlassCard } from './GlassCard';
import { UserInput } from '../types';
import { INITIAL_DB, GLOBAL_100 } from '../constants';

interface InputFormProps {
  input: UserInput;
  onChange: (field: keyof UserInput, value: string | number) => void;
  onGenerate: () => void;
  onRandom: () => void;
  onDownload: () => void;
  canDownload: boolean;
  isGenerating: boolean;
}

export const InputForm: React.FC<InputFormProps> = ({
  input,
  onChange,
  onGenerate,
  onRandom,
  onDownload,
  canDownload,
  isGenerating
}) => {
  const [prompt, setPrompt] = useState('');

  // Advanced Parsing Logic
  const analyzeAndGenerate = () => {
    if (!prompt.trim()) {
      onRandom(); // Empty input triggers random
      return;
    }

    let newAge = '';
    let newStart = '';
    let newGoal = '';
    let newMonths = 36;
    let newJob = '프리랜서';

    const text = prompt;

    // 1. Age (e.g., 53세, 53살, 20대)
    const ageMatch = text.match(/(\d+)(?:세|살)/);
    if (ageMatch) newAge = ageMatch[1];

    // 2. Months/Years (e.g., 3년, 36개월)
    const yearMatch = text.match(/(\d+)(?:년)/);
    const monthMatch = text.match(/(\d+)(?:개월|달)/);
    if (yearMatch) newMonths = parseInt(yearMatch[1]) * 12;
    else if (monthMatch) newMonths = parseInt(monthMatch[1]);

    // 3. Country/City Detection (Goal)
    // Scan Global 100 DB first
    for (const [key, config] of Object.entries(GLOBAL_100)) {
        if (text.includes(key) || config.cities.some(c => text.includes(c))) {
            newGoal = key; // Set country key as goal initially for logic
            // Try to find specific city in text
            const city = config.cities.find(c => text.includes(c));
            if (city) newGoal = city;
            break;
        }
    }
    // Fallback regex for "Start -> Goal" structure
    if (!newGoal) {
        // "Seoul to New York", "서울에서 뉴욕으로"
        const directionMatch = text.match(/([가-힣a-zA-Z]+)(?:에서|부터)\s*([가-힣a-zA-Z]+)(?:(?:으?로)|(?:에))/);
        if (directionMatch) {
            newStart = directionMatch[1];
            newGoal = directionMatch[2];
        } else {
             // Simple "Goal" extraction context
             const goalMatch = text.match(/([가-힣a-zA-Z]+)(?:(?:으?로)|(?:에))\s*(?:이민|이주|가고|살고)/);
             if (goalMatch) newGoal = goalMatch[1];
        }
    }

    // 4. Job Detection (Simple Keyword)
    const jobs = ['개발자', '디자이너', '용접공', '간호사', '요리사', '사업', '은퇴', '유학', '주재원', '인테리어', '자영업'];
    const foundJob = jobs.find(j => text.includes(j));
    if (foundJob) newJob = foundJob;

    // Update State
    if (newAge) onChange('age', newAge);
    if (newStart) onChange('start', newStart);
    else onChange('start', '한국'); // Default start
    if (newGoal) onChange('goal', newGoal);
    if (newJob) onChange('job', newJob);
    onChange('months', newMonths);

    // Trigger Generation
    setTimeout(onGenerate, 100);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      analyzeAndGenerate();
    }
  };

  return (
    <GlassCard className="p-1">
      <div className="relative group">
        <div className="absolute -inset-1 bg-gradient-to-r from-emerald-500 via-teal-500 to-indigo-500 rounded-2xl blur opacity-25 group-hover:opacity-50 transition duration-1000 group-hover:duration-200"></div>
        <div className="relative bg-gray-900 ring-1 ring-white/10 rounded-2xl p-4 md:p-6 space-y-4">

          <div className="flex justify-between items-center mb-2">
            <label className="text-emerald-400 font-bold text-sm tracking-wider uppercase flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
              AI Simulation Input
            </label>
            <div className="text-xs text-gray-400">100개국 데이터 연동됨</div>
          </div>

          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            onKeyDown={handleKeyDown}
            className="w-full bg-transparent text-white text-lg md:text-xl font-medium placeholder-gray-600 focus:outline-none resize-none h-24 leading-relaxed"
            placeholder="예) 53세 인테리어 업자인데 한국 떠나서 오스트리아 빈으로 이민가고 싶어. 3년 정도 생각중이야."
          />

          <div className="flex justify-between items-center pt-2 border-t border-white/5">
            <div className="flex gap-2">
               <button onClick={onRandom} className="text-xs bg-white/5 hover:bg-white/10 px-3 py-2 rounded-lg text-gray-400 transition-colors flex items-center gap-1">
                 <span>🎲</span> 예시 랜덤 입력
               </button>
               {canDownload && (
                 <button onClick={onDownload} className="text-xs bg-purple-500/10 hover:bg-purple-500/20 px-3 py-2 rounded-lg text-purple-300 transition-colors flex items-center gap-1 border border-purple-500/20">
                   <span>📄</span> PDF 저장
                 </button>
               )}
            </div>

            <button 
              onClick={analyzeAndGenerate}
              disabled={isGenerating}
              className={`px-6 py-3 rounded-xl font-bold text-white shadow-lg flex items-center gap-2 transition-all transform active:scale-95 ${
                isGenerating 
                  ? 'bg-gray-700 cursor-not-allowed' 
                  : 'bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 shadow-emerald-900/20'
              }`}
            >
              {isGenerating ? (
                <>
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  분석중...
                </>
              ) : (
                <>
                  <span>🚀</span> 시뮬레이션 시작
                </>
              )}
            </button>
          </div>
        </div>
      </div>
    </GlassCard>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { InputForm } from './components/InputForm';
import { ResultSection, downloadPDFElement } from './components/ResultSection';
import { AdBanner } from './components/AdBanner';
import { ActionButtons } from './components/ActionButtons';
import { Toast } from './components/Toast';
import { AdminDashboard } from './components/AdminDashboard';
import { INITIAL_DB, RANDOM_SCENARIOS, GLOBAL_100, detectCountry, DRY_WRITER_VARS } from './constants';
import { UserInput, StoryResult, ScenarioDB, ScenarioData } from './types';
import { GlassCard } from './components/GlassCard';

function App() {
  const [db, setDb] = useState<ScenarioDB>(INITIAL_DB);
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  const [input, setInput] = useState<UserInput>({
    age: '',
    job: '',
    start: '',
    goal: '',
    months: 36,
    country: ''
  });
  const [result, setResult] = useState<StoryResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // Initial Load
  useEffect(() => {
    if (window.location.hash === '#admin') setShowAdminLogin(true);
    // Removed legacy credit loading
  }, []);

  const handleAdminLogin = () => {
    if (adminPassword === '1234') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setToastMessage("🔓 관리자 모드로 접속했습니다.");
    } else {
      alert("비밀번호가 올바르지 않습니다.");
    }
  };

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const generateStory = useCallback(() => {
    setLoading(true);

    // Simulate API processing time
    setTimeout(() => {
      const age = input.age || '35';
      const job = input.job || '자영업';
      const start = input.start || '서울';
      const goal = input.goal || '해외';
      const months = input.months || 24;

      // --- DRY WRITER ENGINE ---
      const countryKey = input.country || detectCountry(goal);
      const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];

      // Random Helpers
      const pick = (arr: string[]) => arr[Math.floor(Math.random() * arr.length)];
      const randInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

      const religion = pick(DRY_WRITER_VARS.religions);
      const obstacle1 = pick(DRY_WRITER_VARS.obstacles1);
      const failure1 = pick(DRY_WRITER_VARS.failures1);
      const obstacle2 = pick(DRY_WRITER_VARS.obstacles2);
      const solution = pick(DRY_WRITER_VARS.solutions);
      const conclusion = pick(DRY_WRITER_VARS.conclusions);
      const expense = pick(DRY_WRITER_VARS.expenses);

      const scenarioData: ScenarioData = {
          success: randInt(40, 95),
          salary: config.avgSalary,
          visa: config.visaName,
          living: randInt(150, 450),
          story: {
              day1: {
                  title: `${goal}는 ${religion}이다`,
                  thought: `나이 ${age}세. ${start}에서의 삶을 정리하고 ${goal}행 비행기에 몸을 실었다. 통장 잔고는 비상금 포함 ${randInt(1000, 5000)}만원.`,
                  action: `${config.prop} 앱으로 월세를 확인하고 숨이 턱 막힌다.`
              },
              initial: {
                  month: 3,
                  title: `${obstacle1}의 습격`,
                  desc: `현실은 잔혹했다. ${failure1} 상황 발생. ${config.currency} 환율 변동으로 생활비가 예상보다 20% 더 빠져나간다.`,
                  highlight: `생존율 ${randInt(15, 40)}% 구간 진입`
              },
              mid: {
                  month: Math.floor(months / 2),
                  title: `${obstacle2} 돌파구`,
                  desc: `죽으라는 법은 없다. ${solution} 방법을 찾아내어 ${config.bank} 계좌에 첫 수익이 찍혔다.`,
                  highlight: `적응도 ${randInt(50, 75)}% 달성`
              },
              final: {
                  month: months,
                  title: conclusion,
                  desc: `어떻게든 버텼다. 하지만 여전히 하루 ${expense}${config.currency === '₩' ? '만 원' : config.currency}은 숨만 쉬어도 나간다. 이것이 ${goal}의 현실이다.`,
                  highlight: `최종 생존율 ${randInt(80, 98)}%`
              }
          },
          resultTable: [
              { item: '주거', before: `${start} 자가`, after: `${goal} 월세`, diff: '하향지원' },
              { item: '자산', before: '유동성 부족', after: '환차손 발생', diff: `-${randInt(1,5)}천만` },
              { item: '심리', before: '막연한 희망', after: '냉철한 현실', diff: '각성' }
          ],
          additionalInfo: {
              obstacles: [obstacle1, obstacle2, '이방인의 고독'],
              alternatives: ['귀국 후 재취업', '현지 로컬 기업 전직', '제3국(동남아) 재이주'],
              nextSteps: {
                  google: `${goal} ${job} 현실`,
                  youtube: `${age}세 ${goal} 이민 브이로그`,
                  pdf: `${config.code.toUpperCase()} 정착 가이드`
              }
          }
      };

      const title = `${age}세 ${start} → ${goal} ${months}개월 생존 리포트`;
      const progress = randInt(30, 92);

      const newResult: StoryResult = {
        title,
        scenarioData,
        progress,
        userInput: { ...input, age, job, start, goal, months },
        timestamp: new Date().toLocaleTimeString()
      };

      setResult(newResult);
      setLoading(false);

      localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput }));

      // Auto scroll to result
      setTimeout(() => {
        const resultEl = document.getElementById('result-anchor');
        if (resultEl) resultEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 100);

    }, 1500); // 1.5s delay for "Analysis" feel
  }, [input]);

  const handleRandom = () => {
    const random = RANDOM_SCENARIOS[Math.floor(Math.random() * RANDOM_SCENARIOS.length)];
    if (random) {
        // Just fill the prompt via state update if we could, but here we update input directly
        // and trigger generation.
        setInput(prev => ({ ...prev, ...random, country: '' }));
        setToastMessage("🎲 랜덤 시나리오를 구성했습니다.");
        setTimeout(generateStory, 500);
    }
  };

  const handleDownload = () => {
    if (result) {
      downloadPDFElement('pdf-content', `희망구매_${result.userInput.goal}_${Date.now()}`);
      setToastMessage("📄 리포트가 PDF로 저장되었습니다.");
    }
  };

  const handleSearch = (type: 'google' | 'youtube') => {
    const qGoal = input.goal || '이민';
    const qJob = input.job || '취업';
    const url = type === 'google' 
      ? `https://google.com/search?q=${qGoal} ${qJob} 현실 비용`
      : `https://youtube.com/results?search_query=${qGoal} ${qJob} 브이로그`;
    window.open(url);
  };

  // --- Render ---
  return (
    <div className="min-h-screen bg-[#0f172a] text-white font-sans selection:bg-emerald-500 selection:text-white">
       {/* Background Elements */}
       <div className="fixed inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-indigo-600/20 rounded-full blur-[100px]"></div>
          <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-emerald-600/10 rounded-full blur-[100px]"></div>
       </div>

      <div className="relative max-w-xl mx-auto min-h-screen flex flex-col pb-safe">

        {/* Header Section */}
        <div className="p-4 md:pt-8">
           <Header 
             scenarioCount={0} 
             lastVerified={db.lastVerified}
             onAdminClick={() => setShowAdminLogin(true)}
           />
        </div>

        {/* Main Content */}
        <div className="flex-1 px-4 space-y-6">

            <InputForm 
              input={input}
              onChange={handleInputChange}
              onGenerate={generateStory}
              onRandom={handleRandom}
              onDownload={handleDownload}
              canDownload={!!result}
              isGenerating={loading}
            />

            <div id="result-anchor"></div>
            <ResultSection result={result} loading={loading} />

            <AdBanner />

            <ActionButtons 
              onGoogleSearch={() => handleSearch('google')}
              onYoutubeSearch={() => handleSearch('youtube')}
              onRandom={handleRandom}
              onRefresh={() => window.location.reload()}
              onReward={() => {}} // No-op now
            />
        </div>

        {/* Footer Padding */}
        <div className="h-12"></div>
      </div>

      {/* Admin Modal */}
      {showAdminLogin && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
            <GlassCard className="p-8 w-full max-w-sm text-center space-y-6 border border-white/20">
              <h2 className="text-2xl font-bold bg-gradient-to-r from-white to-gray-400 bg-clip-text text-transparent">System Access</h2>
              <input 
                type="password" 
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAdminLogin()}
                className="w-full p-4 bg-white/5 rounded-xl text-center text-xl font-bold border border-white/10 focus:border-emerald-500 focus:outline-none transition-colors"
                placeholder="Passcode"
                autoFocus
              />
              <div className="flex gap-4">
                <button onClick={() => setShowAdminLogin(false)} className="flex-1 py-3 bg-gray-700/50 hover:bg-gray-700 rounded-xl transition-colors font-medium">Cancel</button>
                <button onClick={handleAdminLogin} className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl transition-colors font-bold shadow-lg shadow-emerald-900/50">Enter</button>
              </div>
            </GlassCard>
          </div>
      )}

      {isAdmin && <AdminDashboard db={db} onUpdateDb={setDb} onClose={() => setIsAdmin(false)} />}

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

