export const INITIAL_DB: ScenarioDB = {
  rates: { CAD: 1080, EUR: 1540, CHF: 1620, USD: 1380, AUD: 920, JPY: 910, VND: 0.055, GBP: 1750, SGD: 1030, THB: 38, IDR: 0.088 },
