export const RANDOM_SCENARIOS: Partial<UserInput>[] = [
  { age: '48', job: '용접공', start: '울산', goal: '노르웨이' },
  { age: '53', job: '인테리어', start: '의정부', goal: '강남' },
  { age: '42', job: '갤러리운영', start: '서울', goal: '통영' },
  { age: '28', job: '서퍼', start: '대구', goal: '양양' },
  { age: '39', job: '민박창업', start: '인천', goal: '울릉도' },
  { age: '50', job: '은퇴', start: '오하이오', goal: '플로리다' },
  { age: '53', job: 'IT개발자', start: '판교', goal: '시부야' },
