export const detectCountry = (text: string): string => {
  const t = text.toLowerCase();
  for (const [key, config] of Object.entries(GLOBAL_100)) {
    if (t.includes(key)) return key;
    if (config.cities.some(city => t.includes(city.toLowerCase()))) return key;
    if (key === 'korea' && /한국|서울|강남|의정부|부천|수원|판교/.test(t)) return key;
    if (key === 'japan' && /일본|도쿄|오사카|사이타마|시부야/.test(t)) return key;
    if (key === 'usa' && /미국|아메리카|오하이오|플로리다/.test(t)) return key;
    if (key === 'thailand' && /태국|치앙마이|방콕/.test(t)) return key;
    if (key === 'vietnam' && /베트남|다낭|하노이/.test(t)) return key;
    if (key === 'indonesia' && /인도네시아|발리/.test(t)) return key;
  }
  return 'default';
};

