export const RANDOM_SCENARIOS: Partial<UserInput>[] = [
  { age: '52', job: '은퇴', start: '싱가포르', goal: '포르투갈' },
  { age: '45', job: '프리랜서', start: '부산', goal: '발리' },
  { age: '53', job: '가장', start: '의정부', goal: '강남' },
  { age: '38', job: '워케이션', start: '도쿄', goal: '호주' },
];

import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { InputForm } from './components/InputForm';
import { ResultSection, downloadPDFElement } from './components/ResultSection';
import { AdBanner } from './components/AdBanner';
import { ActionButtons } from './components/ActionButtons';
import { Toast } from './components/Toast';
import { AdminDashboard } from './components/AdminDashboard';
import { INITIAL_DB, RANDOM_SCENARIOS, GLOBAL_100, detectCountry, DEFAULT_TEMPLATES } from './constants';
import { UserInput, StoryResult, ScenarioDB, ScenarioData, ScenarioTemplate } from './types';
import { GlassCard } from './components/GlassCard';

function App() {
  const [db, setDb] = useState<ScenarioDB>(INITIAL_DB);
  // Persistent Templates State
  const [templates, setTemplates] = useState<ScenarioTemplate[]>(() => {
    const saved = localStorage.getItem('app_templates');
    return saved ? JSON.parse(saved) : DEFAULT_TEMPLATES;
  });

  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  const [input, setInput] = useState<UserInput>({
    age: '',
    job: '',
    start: '',
    goal: '',
    months: 24,
    country: ''
  });
  const [result, setResult] = useState<StoryResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (window.location.hash === '#admin') setShowAdminLogin(true);
  }, []);

  // Save templates to LocalStorage whenever they change
  useEffect(() => {
    localStorage.setItem('app_templates', JSON.stringify(templates));
  }, [templates]);

  const handleAdminLogin = () => {
    if (adminPassword === '1234') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setToastMessage("🔓 관리자 모드로 접속했습니다.");
    } else {
      alert("비밀번호가 올바르지 않습니다.");
    }
  };

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const generateStory = useCallback(() => {
    setLoading(true);
    setResult(null); 

    setTimeout(() => {
      // 1. Prepare Variables
      const age = input.age || '35';
      const job = input.job || '자영업';
      const start = input.start || '서울';
      const goal = input.goal || '해외';
      const months = input.months || 24;
      const countryKey = input.country || detectCountry(goal);
      const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];

      // 2. Select Template Logic (Exact Matching Priority)
      // Note: Now using the dynamic `templates` state instead of hardcoded constants
      let selectedTemplate = templates[0]; // Default

      const jobLower = job.toLowerCase();
      const goalLower = goal.toLowerCase();
      const startLower = start.toLowerCase();

      // Priority 1: Singapore -> Portugal (Specific)
      if ((startLower.includes('싱가포르') || startLower.includes('싱가폴')) && (goalLower.includes('포르투갈') || goalLower.includes('리스본'))) {
         const match = templates.find(t => t.id === 'template_sg_pt' || t.tags.includes('portugal'));
         if (match) selectedTemplate = match;
      }
      // Priority 2: Bali (Specific)
      else if (goalLower.includes('발리') || goalLower.includes('인도네시아')) {
         const match = templates.find(t => t.id === 'template_bali_report' || t.tags.includes('bali'));
         if (match) selectedTemplate = match;
      }
      // Priority 3: Gangnam/Seoul (Specific)
      else if (goalLower.includes('강남') || goalLower.includes('서울') || startLower.includes('의정부') || goalLower.includes('아파트')) {
         const match = templates.find(t => t.id === 'template_gangnam_report' || t.tags.includes('gangnam'));
         if (match) selectedTemplate = match;
      }

      // Fallback: Try to find a generic matching tag
      if (!selectedTemplate) {
          const genericMatch = templates.find(t => 
             t.tags.some(tag => goalLower.includes(tag) || jobLower.includes(tag) || startLower.includes(tag))
          );
          if (genericMatch) selectedTemplate = genericMatch;
      }

      // 3. Inject Variables into Template
      const inject = (text?: string) => {
        if (!text) return "";
        return text
          .replace(/{age}/g, age)
          .replace(/{job}/g, job)
          .replace(/{start}/g, start)
          .replace(/{goal}/g, goal)
          .replace(/{months}/g, months.toString())
          .replace(/{currency}/g, config.currency)
          .replace(/{prop}/g, config.prop)
          .replace(/{bank}/g, config.bank)
          .replace(/{visa}/g, config.visaName);
      };

      const randInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

      const scenarioData: ScenarioData = {
          success: randInt(40, 95),
          salary: config.avgSalary,
          visa: config.visaName,
          living: randInt(100, 450), 
          story: {
              header: inject(selectedTemplate.story.titleTemplate),
              subHeader: inject(selectedTemplate.story.subTemplate),
              stages: selectedTemplate.story.stages.map(s => ({
                label: s.label,
                title: inject(s.title),
                situation: inject(s.content.situation),
                thought: inject(s.content.thought),
                action: inject(s.content.action),
                experiment: inject(s.content.experiment),
                failure: inject(s.content.failure),
                question: inject(s.content.question),
                solution: inject(s.content.solution),
                result: inject(s.content.result),
                reality: inject(s.content.reality),
              })) as [any, any, any, any]
          },
          resultTable: [
              { item: '월 생활비', before: `${config.currency} 4,500`, after: `${config.currency} 3,200`, diff: `-1,300` },
              { item: '자산', before: '유동성 부족', after: '환차익 발생', diff: `+${randInt(1, 15)}%` },
              { item: '의료비', before: '보험 적용', after: '사립 병원', diff: '+200%' },
              { item: '순 저축', before: '100', after: '350', diff: '+250' }
          ],
          additionalInfo: {
              obstacles: ['EU 규제 강화', '환율 변동', '언어 장벽'],
              nextSteps: [
                  { label: '구글 검색', value: `${start} 은퇴자 ${goal} 비자 후기` },
                  { label: '유튜브', value: `${goal} 골든비자 폐지 후 대안` },
                  { label: 'PDF 다운로드', value: `${goal} NIF + 부동산세 가이드` }
              ]
          }
      };

      // Set Title dynamically
      const title = scenarioData.story.header;
      const progress = randInt(50, 92);

      const newResult: StoryResult = {
        title,
        scenarioData,
        progress,
        userInput: { ...input, age, job, start, goal, months },
        timestamp: new Date().toLocaleTimeString()
      };

      setResult(newResult);
      setLoading(false);

      localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput }));

      if (window.innerWidth < 1024) {
          setTimeout(() => {
            const resultEl = document.getElementById('result-anchor');
            if (resultEl) resultEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }, 100);
      }

    }, 1500); 
  }, [input, templates]);

  const handleRandom = () => {
    const random = RANDOM_SCENARIOS[Math.floor(Math.random() * RANDOM_SCENARIOS.length)];
    if (random) {
        setInput(prev => ({ ...prev, ...random, country: '' }));
        setToastMessage("🎲 랜덤 시나리오를 구성했습니다.");
        setTimeout(generateStory, 500);
    }
  };

  const handleDownload = () => {
    if (result) {
      downloadPDFElement('pdf-content', `희망구매_${result.userInput.goal}_${Date.now()}`);
      setToastMessage("📄 리포트가 PDF로 저장되었습니다.");
    }
  };

  const handleSearch = (type: 'google' | 'youtube') => {
    const qGoal = input.goal || '이민';
    const qJob = input.job || '취업';
    const url = type === 'google' 
      ? `https://google.com/search?q=${input.age}세 ${qGoal} ${qJob} 현실 비용`
      : `https://youtube.com/results?search_query=${qGoal} ${qJob} 브이로그`;
    window.open(url);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-white font-sans selection:bg-emerald-500 selection:text-white">
       <div className="fixed inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-indigo-600/20 rounded-full blur-[100px]"></div>
          <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-emerald-600/10 rounded-full blur-[100px]"></div>
       </div>

      <div className="relative w-full max-w-[1400px] mx-auto min-h-screen flex flex-col pb-safe px-4 md:px-6 lg:px-8">

        <div className="pt-4 md:pt-8 pb-6">
           <Header 
             scenarioCount={templates.length} 
             lastVerified={db.lastVerified}
             onAdminClick={() => setShowAdminLogin(true)}
           />
        </div>

        <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-8 items-start">

            <div className="lg:col-span-4 space-y-6 sticky top-8">
                <InputForm 
                  input={input}
                  onChange={handleInputChange}
                  onGenerate={generateStory}
                  onRandom={handleRandom}
                  onDownload={handleDownload}
                  canDownload={!!result}
                  isGenerating={loading}
                />

                <div className="hidden lg:block space-y-6">
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                    <AdBanner />
                </div>
            </div>

            <div className="lg:col-span-8 space-y-6">
                <div id="result-anchor"></div>

                {!result && !loading && (
                    <div className="hidden lg:flex h-full min-h-[400px] items-center justify-center border-2 border-dashed border-white/10 rounded-3xl bg-white/5 text-gray-400">
                        <div className="text-center p-8">
                            <div className="text-4xl mb-4">👈</div>
                            <h3 className="text-xl font-bold mb-2">시뮬레이션을 시작하세요</h3>
                            <p className="text-sm">왼쪽 패널에 정보를 입력하고<br/>미래를 확인해보세요.</p>
                        </div>
                    </div>
                )}

                <ResultSection result={result} loading={loading} />

                <div className="lg:hidden space-y-6">
                    <AdBanner />
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                </div>
            </div>
        </div>

        <div className="h-12"></div>
      </div>

      {showAdminLogin && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
            <GlassCard className="p-8 w-full max-w-sm text-center space-y-6 border border-white/20">
              <h2 className="text-2xl font-bold bg-gradient-to-r from-white to-gray-400 bg-clip-text text-transparent">System Access</h2>
              <input 
                type="password" 
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAdminLogin()}
                className="w-full p-4 bg-white/5 rounded-xl text-center text-xl font-bold border border-white/10 focus:border-emerald-500 focus:outline-none transition-colors"
                placeholder="Passcode"
                autoFocus
              />
              <div className="flex gap-4">
                <button onClick={() => setShowAdminLogin(false)} className="flex-1 py-3 bg-gray-700/50 hover:bg-gray-700 rounded-xl transition-colors font-medium">Cancel</button>
                <button onClick={handleAdminLogin} className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl transition-colors font-bold shadow-lg shadow-emerald-900/50">Enter</button>
              </div>
            </GlassCard>
          </div>
      )}

      {isAdmin && (
        <AdminDashboard 
          db={db} 
          onUpdateDb={setDb} 
          templates={templates} 
          onUpdateTemplates={setTemplates}
          onClose={() => setIsAdmin(false)} 
        />
      )}

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { GlassCard } from './GlassCard';
import { ScenarioDB, ScenarioTemplate } from '../types';
import { DEFAULT_TEMPLATES } from '../constants';

interface AdminDashboardProps {
  db: ScenarioDB;
  onUpdateDb: (newDb: ScenarioDB) => void;
  templates: ScenarioTemplate[];
  onUpdateTemplates: (newTemplates: ScenarioTemplate[]) => void;
  onClose: () => void;
}

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  db, 
  onUpdateDb, 
  templates, 
  onUpdateTemplates, 
  onClose 
}) => {
  const [activeTab, setActiveTab] = useState<'control' | 'templates'>('control');
  const [logs, setLogs] = useState<string[]>([]);

  // Template Editing State
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
  const [jsonInput, setJsonInput] = useState<string>('');
  const [isEditing, setIsEditing] = useState(false);

  const addLog = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const handleVerifyAll = () => {
    addLog("🤖 AI 전체 검증 시작... (Data Integrity Check)");
    setTimeout(() => {
      onUpdateDb({
        ...db,
        lastVerified: new Date().toLocaleString(),
        changes: [
          { type: '시스템', details: '100개 시나리오 정합성 검증 완료', timestamp: new Date().toLocaleString() },
          ...db.changes
        ]
      });
      addLog("✅ 검증 완료. 데이터베이스가 최신 상태입니다.");
    }, 1500);
  };

  const handleSelectTemplate = (t: ScenarioTemplate) => {
    setSelectedTemplateId(t.id);
    setJsonInput(JSON.stringify(t, null, 2));
    setIsEditing(true);
  };

  const handleCreateNew = () => {
    const newTemplate = { ...DEFAULT_TEMPLATES[0], id: `custom_${Date.now()}`, tags: ['new'] };
    setSelectedTemplateId(null);
    setJsonInput(JSON.stringify(newTemplate, null, 2));
    setIsEditing(true);
  };

  const handleSaveTemplate = () => {
    try {
      const parsed = JSON.parse(jsonInput) as ScenarioTemplate;
      if (!parsed.id || !parsed.story) throw new Error("Invalid Format");

      const exists = templates.find(t => t.id === parsed.id);
      let newTemplates;

      if (exists) {
        newTemplates = templates.map(t => t.id === parsed.id ? parsed : t);
        addLog(`📝 템플릿 수정됨: ${parsed.id}`);
      } else {
        newTemplates = [parsed, ...templates];
        addLog(`✨ 새 템플릿 추가됨: ${parsed.id}`);
      }

      onUpdateTemplates(newTemplates);
      setIsEditing(false);
      setSelectedTemplateId(null);
    } catch (e) {
      alert("JSON 형식이 올바르지 않습니다. 다시 확인해주세요.");
    }
  };

  const handleDeleteTemplate = (id: string) => {
    if (confirm("정말 이 템플릿을 삭제하시겠습니까?")) {
      const newTemplates = templates.filter(t => t.id !== id);
      onUpdateTemplates(newTemplates);
      addLog(`🗑️ 템플릿 삭제됨: ${id}`);
      if (selectedTemplateId === id) {
        setIsEditing(false);
        setSelectedTemplateId(null);
      }
    }
  };

  const handleResetDefaults = () => {
    if (confirm("모든 커스텀 템플릿이 삭제되고 초기 상태로 복구됩니다. 계속하시겠습니까?")) {
      onUpdateTemplates(DEFAULT_TEMPLATES);
      addLog("🔄 시스템 초기화 완료 (Factory Reset)");
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-[#0f172a] text-white overflow-hidden flex flex-col">
      {/* Header */}
      <div className="bg-[#1e293b] border-b border-white/10 p-4 md:p-6 flex justify-between items-center shadow-lg z-10">
        <h1 className="text-2xl md:text-3xl font-black text-emerald-400 flex items-center gap-3">
          🛡️ Admin Console
          <span className="text-xs bg-emerald-500/20 text-emerald-300 px-2 py-1 rounded border border-emerald-500/20">Persistent Mode</span>
        </h1>
        <button onClick={onClose} className="px-6 py-2 bg-red-500/10 hover:bg-red-500/20 text-red-400 rounded-lg font-bold transition-all border border-red-500/20">
          Close
        </button>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-white/10 bg-[#1e293b]/50">
        <button 
          onClick={() => setActiveTab('control')}
          className={`flex-1 py-4 font-bold text-sm uppercase tracking-widest transition-colors ${activeTab === 'control' ? 'bg-emerald-600 text-white' : 'text-gray-400 hover:text-white'}`}
        >
          System Control
        </button>
        <button 
          onClick={() => setActiveTab('templates')}
          className={`flex-1 py-4 font-bold text-sm uppercase tracking-widest transition-colors ${activeTab === 'templates' ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:text-white'}`}
        >
          Template Manager ({templates.length})
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden relative">

        {/* TAB: CONTROL */}
        {activeTab === 'control' && (
          <div className="h-full overflow-y-auto p-6 md:p-8 space-y-8">
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <GlassCard className="p-6 text-center">
                    <div className="text-4xl mb-2">💾</div>
                    <div className="font-bold mb-2">데이터 영구 보존</div>
                    <div className="text-xs text-gray-400">LocalStorage 연동됨<br/>브라우저를 닫아도 유지</div>
                </GlassCard>
                <GlassCard className="p-6 text-center">
                    <div className="text-4xl mb-2">⚡</div>
                    <div className="font-bold mb-2">실시간 검증</div>
                    <button onClick={handleVerifyAll} className="mt-2 px-4 py-2 bg-emerald-600 rounded-lg text-xs font-bold w-full">실행</button>
                </GlassCard>
                <GlassCard className="p-6 text-center">
                    <div className="text-4xl mb-2">🔄</div>
                    <div className="font-bold mb-2">초기화</div>
                    <button onClick={handleResetDefaults} className="mt-2 px-4 py-2 bg-orange-600 rounded-lg text-xs font-bold w-full">Factory Reset</button>
                </GlassCard>
             </div>

             <GlassCard className="p-6">
                <h2 className="text-xl font-bold mb-4">📜 System Logs</h2>
                <div className="h-64 bg-black/30 rounded-xl p-4 overflow-y-auto font-mono text-sm space-y-2 text-gray-300">
                  {logs.length === 0 && <span className="opacity-50">시스템 대기 중...</span>}
                  {logs.map((log, i) => (
                    <div key={i} className="border-b border-white/5 pb-1">{log}</div>
                  ))}
                </div>
             </GlassCard>
          </div>
        )}

        {/* TAB: TEMPLATES */}
        {activeTab === 'templates' && (
          <div className="h-full flex flex-col md:flex-row">
            {/* List Sidebar */}
            <div className="w-full md:w-1/3 border-r border-white/10 bg-black/20 flex flex-col h-full">
               <div className="p-4 border-b border-white/10 flex justify-between items-center">
                  <span className="font-bold text-gray-400">Available Templates</span>
                  <button onClick={handleCreateNew} className="text-xs bg-emerald-600 px-3 py-1 rounded text-white font-bold hover:bg-emerald-500">+ New</button>
               </div>
               <div className="flex-1 overflow-y-auto p-2 space-y-2">
                  {templates.map(t => (
                    <div 
                      key={t.id} 
                      onClick={() => handleSelectTemplate(t)}
                      className={`p-3 rounded-lg cursor-pointer border transition-all ${selectedTemplateId === t.id ? 'bg-indigo-600 border-indigo-400' : 'bg-white/5 border-transparent hover:bg-white/10'}`}
                    >
                       <div className="flex justify-between">
                         <span className="font-bold text-sm truncate">{t.id}</span>
                         <span className={`text-[10px] px-1.5 py-0.5 rounded uppercase ${t.type === 'report' ? 'bg-blue-500/20 text-blue-300' : 'bg-purple-500/20 text-purple-300'}`}>{t.type}</span>
                       </div>
                       <div className="text-xs text-gray-400 mt-1 truncate">{t.tags.join(', ')}</div>
                    </div>
                  ))}
               </div>
            </div>

            {/* Editor Area */}
            <div className="flex-1 flex flex-col h-full bg-[#1e293b]">
               {isEditing ? (
                 <>
                   <div className="p-4 border-b border-white/10 flex justify-between items-center bg-black/20">
                      <div className="text-sm text-gray-400">Editing: <span className="text-white font-bold">{JSON.parse(jsonInput).id || 'New Template'}</span></div>
                      <div className="flex gap-2">
                         {selectedTemplateId && (
                           <button onClick={() => handleDeleteTemplate(selectedTemplateId)} className="px-4 py-2 bg-red-500/20 text-red-400 hover:bg-red-500/30 rounded font-bold text-xs">Delete</button>
                         )}
                         <button onClick={handleSaveTemplate} className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 rounded font-bold text-xs text-white shadow-lg">Save Changes</button>
                      </div>
                   </div>
                   <div className="flex-1 relative">
                      <textarea 
                        value={jsonInput}
                        onChange={(e) => setJsonInput(e.target.value)}
                        className="w-full h-full bg-[#0f172a] text-emerald-300 font-mono text-xs p-6 focus:outline-none resize-none leading-relaxed"
                        spellCheck={false}
                      />
                   </div>
                 </>
               ) : (
                 <div className="flex-1 flex flex-col items-center justify-center text-gray-500">
                    <div className="text-4xl mb-4 opacity-50">👈</div>
                    <p>Select a template to edit or create a new one.</p>
                 </div>
               )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

