                  canDownload={!!result}
                  isGenerating={loading}
                />

                <div className="hidden lg:block space-y-6">
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
