                    </p>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 font-sans">
                        {downloads.map((resource, idx) => (
                           <ResourceCard key={idx} resource={resource} />
                        ))}
                    </div>
                  </div>
                )}
             </div>
          </div>
        </div>

      </div>
    </div>
  );
};

