                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                </div>
            </div>
        </div>

        <div className="h-12"></div>
      </div>

      {showAdminLogin && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
            <GlassCard className="p-8 w-full max-w-sm text-center space-y-6 border border-white/20">
              <h2 className="text-2xl font-bold bg-gradient-to-r from-white to-gray-400 bg-clip-text text-transparent">System Access</h2>
              <input 
                type="password" 
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAdminLogin()}
                className="w-full p-4 bg-white/5 rounded-xl text-center text-xl font-bold border border-white/10 focus:border-emerald-500 focus:outline-none transition-colors"
                placeholder="Passcode"
                autoFocus
              />
              <div className="flex gap-4">
                <button onClick={() => setShowAdminLogin(false)} className="flex-1 py-3 bg-gray-700/50 hover:bg-gray-700 rounded-xl transition-colors font-medium">Cancel</button>
                <button onClick={handleAdminLogin} className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl transition-colors font-bold shadow-lg shadow-emerald-900/50">Enter</button>
              </div>
            </GlassCard>
          </div>
      )}

      {isAdmin && (
        <AdminDashboard 
          db={db} 
          onUpdateDb={setDb} 
          templates={templates} 
          onUpdateTemplates={setTemplates}
          onClose={() => setIsAdmin(false)} 
        />
      )}

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { GlassCard } from './GlassCard';
import { ScenarioDB, ScenarioTemplate, DownloadableResource, UserInput } from '../types';
import { DEFAULT_TEMPLATES } from '../constants';

interface AdminDashboardProps {
  db: ScenarioDB;
  onUpdateDb: (newDb: ScenarioDB) => void;
  templates: ScenarioTemplate[];
  onUpdateTemplates: (newTemplates: ScenarioTemplate[]) => void;
  onClose: () => void;
}

const RandomSampleEditor: React.FC<{db: ScenarioDB, onUpdateDb: (newDb: ScenarioDB) => void}> = ({ db, onUpdateDb }) => {
    const [samples, setSamples] = useState(db.randomSamples || []);

    const handleUpdate = (index: number, field: keyof UserInput, value: string) => {
        const newSamples = [...samples];
        newSamples[index] = { ...newSamples[index], [field]: value };
        setSamples(newSamples);
    };

    const handleSave = () => {
        onUpdateDb({ ...db, randomSamples: samples });
        alert("랜덤 예시가 저장되었습니다.");
    };

    const handleAdd = () => {
        setSamples([...samples, { age: '40', job: '직장인', start: '서울', goal: '제주' }]);
    };

    const handleRemove = (index: number) => {
        const newSamples = [...samples];
        newSamples.splice(index, 1);
        setSamples(newSamples);
    };

    return (
        <div className="h-full overflow-y-auto p-6 md:p-8 space-y-6">
            <GlassCard className="p-6 border-l-4 border-l-purple-500">
                 <div className="flex justify-between items-center mb-4">
                    <div>
                        <h3 className="text-xl font-bold">🔀 랜덤 예시 관리</h3>
                        <p className="text-xs text-gray-400 mt-1">사용자가 '랜덤 입력' 버튼을 눌렀을 때 나타날 시나리오를 관리합니다.</p>
                    </div>
                    <button onClick={handleSave} className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 rounded font-bold text-xs text-white shadow-lg">
                        전체 저장
                    </button>
                 </div>

                 <div className="space-y-4">
                    {samples.map((sample, index) => (
                         <div key={index} className="bg-white/5 border border-white/10 rounded-xl p-4 relative group">
                            <button onClick={() => handleRemove(index)} className="absolute top-2 right-2 text-red-400 hover:text-red-300 bg-black/20 rounded-full w-6 h-6 flex items-center justify-center opacity-50 group-hover:opacity-100">
                                ×
                            </button>
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                                <input value={sample.age || ''} onChange={(e) => handleUpdate(index, 'age', e.target.value)} placeholder="나이" className="bg-black/30 p-2 rounded text-sm w-full border border-transparent focus:border-purple-500 focus:outline-none"/>
                                <input value={sample.job || ''} onChange={(e) => handleUpdate(index, 'job', e.target.value)} placeholder="직업" className="bg-black/30 p-2 rounded text-sm w-full border border-transparent focus:border-purple-500 focus:outline-none"/>
                                <input value={sample.start || ''} onChange={(e) => handleUpdate(index, 'start', e.target.value)} placeholder="출발지" className="bg-black/30 p-2 rounded text-sm w-full border border-transparent focus:border-purple-500 focus:outline-none"/>
                                <input value={sample.goal || ''} onChange={(e) => handleUpdate(index, 'goal', e.target.value)} placeholder="목표" className="bg-black/30 p-2 rounded text-sm w-full border border-transparent focus:border-purple-500 focus:outline-none"/>
                            </div>
                         </div>
                    ))}
                    <button onClick={handleAdd} className="w-full py-3 bg-white/5 hover:bg-white/10 border border-dashed border-white/20 rounded-xl text-sm font-bold text-gray-400 hover:text-white transition-colors">
                        + 새 예시 추가
                    </button>
                 </div>
            </GlassCard>
        </div>
    );
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  db, 
  onUpdateDb, 
  templates, 
  onUpdateTemplates, 
  onClose 
}) => {
  const [activeTab, setActiveTab] = useState<'control' | 'templates' | 'samples'>('control');
  const [logs, setLogs] = useState<string[]>([]);

  // Template Editing State
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
  const [jsonInput, setJsonInput] = useState<string>('');
  const [isEditing, setIsEditing] = useState(false);
  const [editMode, setEditMode] = useState<'json' | 'easy'>('easy'); // New Toggle

  // Temporary state for Easy Editor
  const [easyData, setEasyData] = useState<ScenarioTemplate | null>(null);

  const addLog = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const handleVerifyAll = () => {
    addLog("🤖 AI 전체 검증 시작... (Data Integrity Check)");
    setTimeout(() => {
      onUpdateDb({
        ...db,
        lastVerified: new Date().toLocaleString(),
        changes: [
          { type: '시스템', details: '100개 시나리오 정합성 검증 완료', timestamp: new Date().toLocaleString() },
          ...db.changes
        ]
      });
      addLog("✅ 검증 완료. 데이터베이스가 최신 상태입니다.");
    }, 1500);
  };

  const handleSelectTemplate = (t: ScenarioTemplate) => {
    setSelectedTemplateId(t.id);
    const jsonStr = JSON.stringify(t, null, 2);
    setJsonInput(jsonStr);
    setEasyData(JSON.parse(jsonStr)); // Deep copy
    setIsEditing(true);
  };

  const handleCreateNew = () => {
    const newTemplate = { ...DEFAULT_TEMPLATES[0], id: `custom_${Date.now()}`, tags: ['new'] };
    setSelectedTemplateId(null);
    const jsonStr = JSON.stringify(newTemplate, null, 2);
    setJsonInput(jsonStr);
    setEasyData(newTemplate);
    setIsEditing(true);
  };

  const handleSaveTemplate = () => {
    try {
      // Use easyData if in easy mode, otherwise parse jsonInput
      const payload = editMode === 'easy' && easyData ? easyData : JSON.parse(jsonInput);

      if (!payload.id || !payload.story) throw new Error("Invalid Format");

      const exists = templates.find(t => t.id === payload.id);
      let newTemplates;

      if (exists) {
        newTemplates = templates.map(t => t.id === payload.id ? payload : t);
        addLog(`📝 템플릿 수정됨: ${payload.id}`);
      } else {
        newTemplates = [payload, ...templates];
        addLog(`✨ 새 템플릿 추가됨: ${payload.id}`);
      }

      onUpdateTemplates(newTemplates);

      // Update local states to reflect save
      setJsonInput(JSON.stringify(payload, null, 2));
      setEasyData(payload);

      // Don't close editing, just notify
      alert("저장되었습니다.");
    } catch (e) {
      alert("데이터 형식이 올바르지 않습니다. JSON 탭을 확인해주세요.");
    }
  };

  const handleDeleteTemplate = (id: string) => {
    if (confirm("정말 이 템플릿을 삭제하시겠습니까?")) {
      const newTemplates = templates.filter(t => t.id !== id);
      onUpdateTemplates(newTemplates);
      addLog(`🗑️ 템플릿 삭제됨: ${id}`);
      if (selectedTemplateId === id) {
        setIsEditing(false);
        setSelectedTemplateId(null);
      }
    }
  };

  const handleResetDefaults = () => {
    if (confirm("모든 커스텀 템플릿이 삭제되고 초기 상태로 복구됩니다. 계속하시겠습니까?")) {
      onUpdateTemplates(DEFAULT_TEMPLATES);
      addLog("🔄 시스템 초기화 완료 (Factory Reset)");
    }
  };

  // --- Easy Editor Handlers ---
  const updateEasyField = (section: 'essay' | 'story', field: string, value: string) => {
    if (!easyData) return;
    setEasyData({
      ...easyData,
      [section]: {
        ...easyData[section as keyof ScenarioTemplate],
        [field]: value
      }
    });
  };

  const addDownloadItem = () => {
    if (!easyData) return;
    const newDownload: DownloadableResource = {
      title: "새로운 자료 제목",
      description: "자료에 대한 설명을 입력하세요.",
      type: "pdf",
      triggerType: "ad",
      fileUrl: ""
    };
    setEasyData({
      ...easyData,
      downloads: [...(easyData.downloads || []), newDownload]
    });
  };

  const removeDownloadItem = (index: number) => {
    if (!easyData || !easyData.downloads) return;
    const newDownloads = [...easyData.downloads];
    newDownloads.splice(index, 1);
    setEasyData({ ...easyData, downloads: newDownloads });
  };

  const updateDownloadItem = (index: number, field: keyof DownloadableResource, value: string) => {
    if (!easyData || !easyData.downloads) return;
    const newDownloads = [...easyData.downloads];
    newDownloads[index] = { ...newDownloads[index], [field]: value };
    setEasyData({ ...easyData, downloads: newDownloads });
  };

  const suggestDownloads = () => {
    if (!easyData) return;
    const tags = easyData.tags.join(' ');
